__d(function(t,e,n,r,o,i,a){o.exports={"Alert.basic":{code:"import { Alert, Block } from '@platform-blocks/react-ui-library';\n\nexport function Demo() {\n  return (\n    <Block>\n      <Alert severity=\"info\" title=\"Heads up\">\n        Use alerts to highlight contextual information inline with page content.\n      </Alert>\n      <Alert severity=\"success\" title=\"Profile saved\">\n        Your changes were stored successfully.\n      </Alert>\n      <Alert severity=\"error\" title=\"Connection issue\">\n        Retry the action or check the status page for outages.\n      </Alert>\n    </Block>\n  );\n}\n",hash:"95f96523dbe5da7d9f8326a082e5a97a5467e5445c006a07a292b69ca3015453",importPath:"../../../../packages/ui/src/components/Alert/demos/basic",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Alert/demos/basic/index.tsx"},"Alert.interactive":{code:"import { useState } from 'react';\nimport { Alert, Button } from '@platform-blocks/react-ui-library';\n\nexport function Demo() {\n  const [visible, setVisible] = useState(true);\n\n  if (!visible) {\n    return (\n      <Button variant=\"outline\" onPress={() => setVisible(true)}>\n        Show alert\n      </Button>\n    );\n  }\n\n  return (\n    <Alert\n      severity=\"warning\"\n      title=\"Draft warning\"\n      withCloseButton\n      onClose={() => setVisible(false)}\n    >\n      Your draft is missing a title. Resolve before publishing.\n    </Alert>\n  );\n}\n",hash:"40e8dcd01913be84525ea390bf3e6344f361255caef9ac43471af56613994118",importPath:"../../../../packages/ui/src/components/Alert/demos/interactive",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Alert/demos/interactive/index.tsx"},"Alert.variants":{code:"import { Alert, Block } from '@platform-blocks/react-ui-library';\n\nexport function Demo() {\n  return (\n    <Block>\n      <Alert variant=\"light\" color=\"primary\" title=\"Light\">\n        Balanced background and border treatment for inline notes.\n      </Alert>\n      <Alert variant=\"outline\" color=\"success\" title=\"Outline\">\n        Subtle emphasis without increasing background contrast.\n      </Alert>\n      <Alert variant=\"filled\" color=\"warning\" title=\"Filled\">\n        High-contrast option for urgent messaging.\n      </Alert>\n      <Alert variant=\"subtle\" color=\"error\" title=\"Subtle\">\n        No background color, but tinted icon and text.\n      </Alert>\n    </Block>\n  );\n}\n",hash:"9d2fc555efc63a4a706679f1aa23c0392d1e958eb261da3521061d9103465360",importPath:"../../../../packages/ui/src/components/Alert/demos/variants",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Alert/demos/variants/index.tsx"}}},3248,[]);
__d(function(e,t,n,a,s,i,o){s.exports={"AppShell.enhanced":{code:"import { AppShell, Block, Text } from '@platform-blocks/react-ui-library';\n\nconst sampleTOC = (\n  <Block>\n    <Text variant=\"h6\" mb=\"sm\">Contents</Text>\n    <Text size=\"sm\" style={{ paddingLeft: 0 }}>Introduction</Text>\n    <Text size=\"sm\" style={{ paddingLeft: 12 }}>Getting Started</Text>\n    <Text size=\"sm\" style={{ paddingLeft: 12 }}>Installation</Text>\n    <Text size=\"sm\" style={{ paddingLeft: 24 }}>NPM Package</Text>\n    <Text size=\"sm\" style={{ paddingLeft: 24 }}>Yarn Setup</Text>\n    <Text size=\"sm\" style={{ paddingLeft: 12 }}>Configuration</Text>\n    <Text size=\"sm\" style={{ paddingLeft: 0 }}>Components</Text>\n    <Text size=\"sm\" style={{ paddingLeft: 12 }}>AppShell</Text>\n    <Text size=\"sm\" style={{ paddingLeft: 12 }}>Layout System</Text>\n    <Text size=\"sm\" style={{ paddingLeft: 0 }}>Examples</Text>\n  </Block>\n);\n\nexport function Demo() {\n  return (\n    <AppShell\n      header={{ height: 60 }}\n      navbar={{ \n        width: 280, \n        breakpoint: 'md',\n        collapsed: { mobile: true }\n      }}\n      autoLayout\n      headerContent={() => (\n        <Text variant=\"h4\" style={{ padding: 16 }}>\n          Documentation\n        </Text>\n      )}\n      navbarContent={() => (\n        <Block p=\"md\">\n          <Text variant=\"h6\">Navigation</Text>\n          <Text size=\"sm\">Getting Started</Text>\n          <Text size=\"sm\">Components</Text>\n          <Text size=\"sm\">Examples</Text>\n          <Text size=\"sm\">API Reference</Text>\n        </Block>\n      )}\n      maxContentWidth={960}\n      tableOfContents={sampleTOC}\n      tableOfContentsWidth={280}\n      hideTableOfContentsOnMobile\n      centerContent\n    >\n      <Block p=\"lg\">\n        <Text variant=\"h1\">Main Content with TOC</Text>\n        <Text>\n          This demonstrates the enhanced AppShell with max width constraints \n          and a table of contents sidebar. The main content area has a maximum \n          width and is centered, while the table of contents appears on the right \n          on desktop screens.\n        </Text>\n        <Text>\n          The layout is fully responsive - on mobile devices, the table of contents \n          is hidden by default to preserve screen space.\n        </Text>\n        <Text variant=\"h2\">Features</Text>\n        <Text>\n          \u2022 Max width constraint for better readability on wide screens\n        </Text>\n        <Text>\n          \u2022 Table of contents sidebar with responsive behavior\n        </Text>\n        <Text>\n          \u2022 Configurable through AppShell or AppShellMain props\n        </Text>\n        <Text>\n          \u2022 Seamless integration with existing AppShell layout system\n        </Text>\n      </Block>\n    </AppShell>\n  );\n}",hash:"f5cc2b9ffba9540abec8e8ce8fc0374c6891088c2ea3935ac8e88db468baf1f4",importPath:"../../../../packages/ui/src/components/AppShell/demos/enhanced",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/AppShell/demos/enhanced/index.tsx"}}},3249,[]);
