__d(function(e,n,o,r,t,s,a){t.exports={"Carousel.basic":{code:"import { Block, Carousel, Text } from '@platform-blocks/react-ui-library';\n\nconst slides = ['#4C1D95', '#155E75', '#166534'];\n\nexport function Demo() {\n  return (\n    <Carousel height={200} loop autoPlay autoPlayInterval={4500} showDots>\n      {slides.map((bg, index) => (\n        <Block key={bg} bg={bg} radius=\"lg\" h=\"full\" align=\"center\" justify=\"center\">\n          <Text variant=\"h3\" color=\"white\">\n            Slide {index + 1}\n          </Text>\n        </Block>\n      ))}\n    </Carousel>\n  );\n}\n",hash:"35d2a9e533323996a96d951b843251a002c0f714ecdaf930e29ae6937899e310",importPath:"../../../../packages/ui/src/components/Carousel/demos/basic",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Carousel/demos/basic/index.tsx"},"Carousel.imageOverlay":{code:"import { Block, Carousel, Image, Text } from '@platform-blocks/react-ui-library';\n\nconst scenes = [\n  { title: 'Mountain escape', src: require('../../../../assets/images/scene-mountains.png') },\n  { title: 'Forest retreat', src: require('../../../../assets/images/scene-forest.png') },\n  { title: 'Desert journey', src: require('../../../../assets/images/scene-desert.png') },\n];\n\nexport function Demo() {\n  return (\n    <Carousel height={280} loop showArrows showDots>\n      {scenes.map(({ title, src }) => (\n        <Block key={title} h=\"full\" radius=\"lg\" style={{ overflow: 'hidden' }}>\n          <Image src={src} w=\"100%\" h=\"100%\" resizeMode=\"cover\" />\n          <Block\n            position=\"absolute\"\n            top={0}\n            right={0}\n            bottom={0}\n            left={0}\n            bg=\"rgba(15,23,42,0.45)\"\n            p=\"lg\"\n            justify=\"flex-end\"\n          >\n            <Text variant=\"h3\" color=\"white\">\n              {title}\n            </Text>\n          </Block>\n        </Block>\n      ))}\n    </Carousel>\n  );\n}\n",hash:"e4375a5758625aa86e677647f37159dbf94a7d2c6f99518cba2ff1145ec8e10f",importPath:"../../../../packages/ui/src/components/Carousel/demos/imageOverlay",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Carousel/demos/imageOverlay/index.tsx"},"Carousel.motionControls":{code:"import { Block, Carousel, Text } from '@platform-blocks/react-ui-library';\n\nfunction slides(colors: string[]) {\n  return colors.map((bg, index) => (\n    <Block key={bg} bg={bg} radius=\"lg\" h=\"full\" align=\"center\" justify=\"center\">\n      <Text variant=\"h4\" color=\"white\">\n        Slide {index + 1}\n      </Text>\n    </Block>\n  ));\n}\n\nexport function Demo() {\n  return (\n    <Block fullWidth gap=\"lg\">\n      <Text variant=\"h5\">Free momentum (dragFree)</Text>\n      <Carousel height={160} dragFree itemsPerPage={2} slideGap={12}>\n        {slides(['#0EA5E9', '#6366F1', '#8B5CF6', '#A855F7'])}\n      </Carousel>\n\n      <Text variant=\"h5\">Locked snaps (skipSnaps off)</Text>\n      <Carousel\n        height={160}\n        itemsPerPage={2}\n        slidesToScroll={1}\n        skipSnaps={false}\n        dragThreshold={45}\n        duration={650}\n        slideGap={12}\n      >\n        {slides(['#F97316', '#EA580C', '#C2410C', '#9A3412'])}\n      </Carousel>\n    </Block>\n  );\n}\n",hash:"23e24063093c172b1547e0c8e1d85e27f69c81bcc3c65381dfde9f192386ef3b",importPath:"../../../../packages/ui/src/components/Carousel/demos/motionControls",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Carousel/demos/motionControls/index.tsx"},"Carousel.multi":{code:"import { Block, Carousel, Text } from '@platform-blocks/react-ui-library';\n\nconst slides = ['#1D4ED8', '#0F766E', '#C026D3', '#B45309', '#7C3AED'];\n\nexport function Demo() {\n  return (\n    <Carousel\n      height={180}\n      loop\n      showDots\n      slideGap={12}\n      itemsPerPage={1}\n      slidesToScroll={1}\n      breakpoints={{\n        '@media (min-width: 768px)': { itemsPerPage: 2 },\n        '@media (min-width: 1200px)': { itemsPerPage: 4 },\n      }}\n    >\n      {slides.map((bg, index) => (\n        <Block key={bg} bg={bg} radius=\"lg\" h=\"full\" align=\"center\" justify=\"center\">\n          <Text variant=\"h4\" color=\"white\">\n            Slide {index + 1}\n          </Text>\n        </Block>\n      ))}\n    </Carousel>\n  );\n}\n",hash:"86605e12ca543e35ebde42def3dda7e76361cfced65e96691ef95fd7965cae8a",importPath:"../../../../packages/ui/src/components/Carousel/demos/multi",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Carousel/demos/multi/index.tsx"},"Carousel.performance":{code:"import { Block, Carousel, Text } from '@platform-blocks/react-ui-library';\n\nconst slides = ['#1E3A8A', '#047857', '#9333EA', '#B91C1C', '#B45309', '#0F766E'];\n\nexport function Demo() {\n  return (\n    <Carousel height={180} loop showArrows windowSize={3} reducedMotion slideGap={12}>\n      {slides.map((bg, index) => (\n        <Block key={bg} bg={bg} radius=\"lg\" h=\"full\" align=\"center\" justify=\"center\">\n          <Text variant=\"h4\" color=\"white\">\n            Slide {index + 1}\n          </Text>\n        </Block>\n      ))}\n    </Carousel>\n  );\n}\n",hash:"7ce3da98bf46d6303833c65eab0dce310c8694101eb726b13a9cf0da12de0dad",importPath:"../../../../packages/ui/src/components/Carousel/demos/performance",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Carousel/demos/performance/index.tsx"},"Carousel.vertical":{code:"import { Block, Carousel, Text } from '@platform-blocks/react-ui-library';\n\nconst slides = ['#DC2626', '#2563EB', '#0F766E'];\n\nexport function Demo() {\n  return (\n    <Carousel\n      orientation=\"vertical\"\n      style={{ height: 280 }}\n      loop\n      autoPlay\n      autoPlayInterval={4500}\n      showArrows\n      showDots\n    >\n      {slides.map((bg, index) => (\n        <Block key={bg} bg={bg} radius=\"lg\" h=\"full\" align=\"center\" justify=\"center\">\n          <Text variant=\"h3\" color=\"white\">\n            Slide {index + 1}\n          </Text>\n        </Block>\n      ))}\n    </Carousel>\n  );\n}\n",hash:"e20933d953558c444954e803a7b8f4a54ed321ebebde1e78e2afcb87d6de149f",importPath:"../../../../packages/ui/src/components/Carousel/demos/vertical",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Carousel/demos/vertical/index.tsx"}}},3266,[]);
__d(function(e,n,t,c,o,r,a){o.exports={"Checkbox.basic":{code:"import { useState } from 'react';\nimport { Block, Checkbox } from '@platform-blocks/react-ui-library';\n\nexport function Demo() {\n  const [checked, setChecked] = useState(false);\n\n  return (\n    <Block w={600}>\n    <Checkbox\n      label=\"Accept terms and conditions\"\n      description={checked ? 'Thanks! You can proceed to the next step.' : 'Check the box to continue.'}\n      checked={checked}\n      onChange={setChecked}\n    />\n    </Block>\n  );\n}\n",hash:"c5467b32b43acca3225548c16abd0994db0aa22b4e1ad27cfac96c49e31215d2",importPath:"../../../../packages/ui/src/components/Checkbox/demos/basic",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Checkbox/demos/basic/index.tsx"},"Checkbox.colors":{code:"import { useState } from 'react';\nimport { Block, Checkbox, Text } from '@platform-blocks/react-ui-library';\n\nconst COLORS = ['primary', 'secondary', 'success', 'warning', 'error'] as const;\n\nexport function Demo() {\n  const [values, setValues] = useState<Record<string, boolean>>({});\n\n  const toggle = (color: string) => {\n    setValues((current) => ({\n      ...current,\n      [color]: !current[color]\n    }));\n  };\n\n  return (\n    <Block>\n      <Text weight=\"medium\">Semantic colors</Text>\n      <Block>\n        {COLORS.map((color) => (\n          <Checkbox\n            key={color}\n            color={color}\n            label={`Color: ${color}`}\n            checked={Boolean(values[color])}\n            onChange={() => toggle(color)}\n          />\n        ))}\n      </Block>\n      <Checkbox\n        color=\"success\"\n        label=\"Default checked\"\n        defaultChecked\n      />\n      <Text variant=\"small\" color=\"muted\">\n        Use `color` to match checkbox accents with message intent while keeping labels readable.\n      </Text>\n    </Block>\n  );\n}\n",hash:"39a32e9aa71ad6bf67f94c70a089e52d8f4a074833b6922656cf5a2b164ad7b4",importPath:"../../../../packages/ui/src/components/Checkbox/demos/colors",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Checkbox/demos/colors/index.tsx"},"Checkbox.indeterminate":{code:"import { useState } from 'react';\nimport { Block, Checkbox } from '@platform-blocks/react-ui-library';\nimport { ITEMS } from './data';\n\nexport function Demo() {\n  const [selected, setSelected] = useState<number[]>([]);\n  const allIds = ITEMS.map((item) => item.id);\n  const allChecked = selected.length === ITEMS.length;\n  const someChecked = selected.length > 0 && !allChecked;\n\n  const toggleAll = () => {\n    setSelected((current) => (current.length === ITEMS.length ? [] : allIds));\n  };\n\n  const toggleItem = (id: number) => {\n    setSelected((current) =>\n      current.includes(id) ? current.filter((itemId) => itemId !== id) : [...current, id]\n    );\n  };\n\n  return (\n    <Block>\n      <Checkbox\n        label={`Select all (${selected.length}/${ITEMS.length})`}\n        checked={allChecked}\n        indeterminate={someChecked}\n        onChange={toggleAll}\n      />\n      <Block pl=\"md\">\n        {ITEMS.map(({ id, label }) => (\n          <Checkbox\n            key={id}\n            label={label}\n            checked={selected.includes(id)}\n            onChange={() => toggleItem(id)}\n          />\n        ))}\n      </Block>\n    </Block>\n  );\n}\n",hash:"098ac6334c5908e7a76a342468031bdfc450fd71d772cd409f460e70cbf47bc0",importPath:"../../../../packages/ui/src/components/Checkbox/demos/indeterminate",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Checkbox/demos/indeterminate/index.tsx",files:[{name:"index.tsx",code:"import { useState } from 'react';\nimport { Block, Checkbox } from '@platform-blocks/react-ui-library';\nimport { ITEMS } from './data';\n\nexport function Demo() {\n  const [selected, setSelected] = useState<number[]>([]);\n  const allIds = ITEMS.map((item) => item.id);\n  const allChecked = selected.length === ITEMS.length;\n  const someChecked = selected.length > 0 && !allChecked;\n\n  const toggleAll = () => {\n    setSelected((current) => (current.length === ITEMS.length ? [] : allIds));\n  };\n\n  const toggleItem = (id: number) => {\n    setSelected((current) =>\n      current.includes(id) ? current.filter((itemId) => itemId !== id) : [...current, id]\n    );\n  };\n\n  return (\n    <Block>\n      <Checkbox\n        label={`Select all (${selected.length}/${ITEMS.length})`}\n        checked={allChecked}\n        indeterminate={someChecked}\n        onChange={toggleAll}\n      />\n      <Block pl=\"md\">\n        {ITEMS.map(({ id, label }) => (\n          <Checkbox\n            key={id}\n            label={label}\n            checked={selected.includes(id)}\n            onChange={() => toggleItem(id)}\n          />\n        ))}\n      </Block>\n    </Block>\n  );\n}\n",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Checkbox/demos/indeterminate/index.tsx"},{name:"data.ts",code:"export let ITEMS = [\n  { id: 1, label: 'Email notifications' },\n  { id: 2, label: 'SMS alerts' },\n  { id: 3, label: 'Push notifications' }\n] as const;",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Checkbox/demos/indeterminate/data.ts"}]},"Checkbox.sizes":{code:"import { Block, Checkbox, Row, Text } from '@platform-blocks/react-ui-library';\n\nconst SIZES = ['xs', 'sm', 'md', 'lg', 'xl', '2xl', '3xl'] as const;\n\nexport function Demo() {\n  return (\n    <Row align=\"center\" gap=\"lg\" wrap=\"wrap\">\n      {SIZES.map((size) => (\n        <Block key={size} align=\"center\">\n          <Checkbox size={size} defaultChecked />\n          <Text variant=\"small\">{size}</Text>\n        </Block>\n      ))}\n    </Row>\n  );\n}\n",hash:"88485284b02a4e9c7b1cca885a5c942e296a6b43107364a92c937a84a9fedccc",importPath:"../../../../packages/ui/src/components/Checkbox/demos/sizes",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Checkbox/demos/sizes/index.tsx"},"Checkbox.states":{code:"import { useState } from 'react';\nimport { Block, Checkbox, Text } from '@platform-blocks/react-ui-library';\n\nexport function Demo() {\n  const [enabled, setEnabled] = useState(true);\n  const [required, setRequired] = useState(true);\n  const [withError, setWithError] = useState(false);\n\n  return (\n    <Block>\n      <Checkbox label=\"Enabled\" checked={enabled} onChange={setEnabled} />\n      <Checkbox label=\"Disabled\" checked={false} disabled />\n      <Checkbox label=\"Required\" required checked={required} onChange={setRequired} />\n      <Checkbox\n        label=\"With error\"\n        error={withError ? 'Selection required' : undefined}\n        checked={withError}\n        onChange={setWithError}\n      />\n    </Block>\n  );\n}\n",hash:"55e9accfa75c964deb126dd30f4db3c3294804bfd0b8a25c1f5b5df8ecdcc703",importPath:"../../../../packages/ui/src/components/Checkbox/demos/states",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Checkbox/demos/states/index.tsx"},"Checkbox.withDescription":{code:"import { useState } from 'react';\nimport { Block, Checkbox, Text } from '@platform-blocks/react-ui-library';\n\nexport function Demo() {\n  const [newsletter, setNewsletter] = useState(false);\n  const [termsAccepted, setTermsAccepted] = useState(false);\n\n  return (\n    <Block style={{ maxWidth: 400 }}>\n      <Checkbox\n        label=\"Receive product updates\"\n        description=\"Get occasional emails about new features and improvements.\"\n        checked={newsletter}\n        onChange={setNewsletter}\n      />\n      <Checkbox\n        label=\"Accept terms of service\"\n        description=\"Required before creating an account.\"\n        error={termsAccepted ? undefined : 'Please accept to continue.'}\n        checked={termsAccepted}\n        onChange={setTermsAccepted}\n        required\n      />\n      <Text variant=\"small\" color=\"muted\">\n        Use `description` for supporting copy and pair with `error` to surface validation details.\n      </Text>\n    </Block>\n  );\n}\n",hash:"403eea16bcfdf95f14d1a5fc22638c22157a8aa35f1d98e694388971141625c8",importPath:"../../../../packages/ui/src/components/Checkbox/demos/withDescription",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Checkbox/demos/withDescription/index.tsx"}}},3267,[]);
__d(function(n,o,e,i,r,a,t){r.exports={"Chip.basic":{code:"import { Chip, Row } from '@platform-blocks/react-ui-library'\n\nexport function Demo() {\n  return (\n    <Row gap={8} wrap=\"wrap\">\n      <Chip>Design</Chip>\n      <Chip>Engineering</Chip>\n      <Chip>Research</Chip>\n    </Row>\n  )\n}\n",hash:"3b65326f3adcca5ae6512ae78c6615996316db65e41fa620ecc11b7099c946af",importPath:"../../../../packages/ui/src/components/Chip/demos/basic",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Chip/demos/basic/index.tsx"},"Chip.colors":{code:"import { Chip, Row } from '@platform-blocks/react-ui-library'\n\nexport function Demo() {\n  return (\n    <Row gap={8} wrap=\"wrap\">\n      <Chip color=\"primary\">Primary</Chip>\n      <Chip color=\"success\">Success</Chip>\n      <Chip color=\"warning\">Warning</Chip>\n      <Chip color=\"error\">Error</Chip>\n      <Chip color=\"gray\">Gray</Chip>\n    </Row>\n  )\n}",hash:"515370aed8e2bb008b1d63b0aef38378792ecbdeae52bb8beb87a7d66b9f682f",importPath:"../../../../packages/ui/src/components/Chip/demos/colors",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Chip/demos/colors/index.tsx"},"Chip.dot":{code:"import { Block, Chip, Row, Text } from '@platform-blocks/react-ui-library'\n\nexport function Demo() {\n  return (\n    <Block fullWidth={false}>\n      <Row gap=\"xs\" wrap=\"wrap\" align=\"center\">\n        <Chip variant=\"filled\" color=\"success\" dot>Active</Chip>\n        <Chip variant=\"light\" color=\"warning\" dot>Pending</Chip>\n        <Chip variant=\"outline\" color=\"error\" dot>Failed</Chip>\n        <Chip variant=\"subtle\" color=\"gray\" dot>Draft</Chip>\n      </Row>\n      <Row gap=\"xs\" wrap=\"wrap\" align=\"center\">\n        <Chip variant=\"light\" color=\"gray\" dotColor=\"#22C55E\" dot>Online</Chip>\n        <Chip variant=\"light\" color=\"gray\" dotColor=\"#F59E0B\" dot>Away</Chip>\n        <Chip variant=\"light\" color=\"gray\" dotColor=\"#EF4444\" dot>Busy</Chip>\n      </Row>\n      <Text size=\"xs\" color=\"muted\">\n        Use <Text size=\"xs\" weight=\"600\">dot</Text> to toggle the indicator and{' '}\n        <Text size=\"xs\" weight=\"600\">dotColor</Text> to set a custom color.\n      </Text>\n    </Block>\n  )\n}\n",hash:"d18dfbdc50792843a76b5e89757015298a8dad9a5e122bdbd2c37919853b93c6",importPath:"../../../../packages/ui/src/components/Chip/demos/dot",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Chip/demos/dot/index.tsx"},"Chip.interactive":{code:"import { useState } from 'react'\nimport { Block, Chip } from '@platform-blocks/react-ui-library'\n\nconst initialSports = [\n  { label: 'Soccer', emoji: '\u26bd' },\n  { label: 'Basketball', emoji: '\ud83c\udfc0' },\n  { label: 'Tennis', emoji: '\ud83c\udfbe' },\n]\n\nexport function Demo() {\n  const [chips, setChips] = useState(initialSports)\n\n  const handleRemove = (chipToRemove: string) => {\n    setChips((current) => current.filter((chip) => chip.label !== chipToRemove))\n  }\n\n  return (\n    <Block>\n      {chips.map((chip) => (\n        <Chip\n          key={chip.label}\n          onRemove={() => handleRemove(chip.label)}\n        >\n          {chip.label}\n        </Chip>\n      ))}\n    </Block>\n  )\n}",hash:"e26a51818f7994b91f63257bd6fa85de31c211180201ca9bfe70ff41854adff6",importPath:"../../../../packages/ui/src/components/Chip/demos/interactive",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Chip/demos/interactive/index.tsx"},"Chip.shadow":{code:"import { Chip, Row } from '@platform-blocks/react-ui-library'\n\nexport function Demo() {\n  return (\n    <Row gap={8} wrap=\"wrap\">\n      <Chip shadow=\"none\">No Shadow</Chip>\n      <Chip shadow=\"xs\">XS Shadow</Chip>\n      <Chip shadow=\"sm\">SM Shadow</Chip>\n      <Chip shadow=\"md\">MD Shadow</Chip>\n      <Chip shadow=\"lg\">LG Shadow</Chip>\n      <Chip shadow=\"xl\">XL Shadow</Chip>\n    </Row>\n  )\n}\n",hash:"9c39b3d06eb2497822e164570cc8edcb0bdfd14ddc16adbd3f13e4c859d9969c",importPath:"../../../../packages/ui/src/components/Chip/demos/shadow",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Chip/demos/shadow/index.tsx"},"Chip.sizes":{code:"import { Block, Chip, Row, Text } from '@platform-blocks/react-ui-library';\n\nconst SIZES = ['xs', 'sm', 'md', 'lg', 'xl', '2xl', '3xl'] as const;\n\nexport function Demo() {\n  return (\n    <Row align=\"center\" gap=\"lg\" wrap=\"wrap\">\n      {SIZES.map((size) => (\n        <Block key={size} align=\"center\">\n          <Chip size={size}>Chip</Chip>\n          <Text variant=\"small\">{size}</Text>\n        </Block>\n      ))}\n    </Row>\n  );\n}\n",hash:"a77243b494db338ed6606e9a73fcdbd93b0ed60426fc56de3a713cac25056fbf",importPath:"../../../../packages/ui/src/components/Chip/demos/sizes",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Chip/demos/sizes/index.tsx"},"Chip.theme-matrix":{code:"import { Block, Card, Chip, DARK_THEME, DEFAULT_THEME, PlatformBlocksThemeProvider, Row, Text } from '@platform-blocks/react-ui-library';\nimport type { ChipProps } from '@platform-blocks/react-ui-library';\n\nconst VARIANTS: NonNullable<ChipProps['variant']>[] = [\n  'filled',\n  'outline',\n  'light',\n  'subtle',\n  'gradient',\n]\n\n// Core palette colors plus one raw custom color, to prove the resolver works for both.\nconst ROWS: { color: string; label: string }[] = [\n  { color: 'primary', label: 'Primary' },\n  { color: 'secondary', label: 'Secondary' },\n  { color: 'success', label: 'Success' },\n  { color: 'warning', label: 'Warning' },\n  { color: 'error', label: 'Error' },\n  { color: 'gray', label: 'Gray' },\n  { color: '#7C3AED', label: 'Custom' },\n]\n\nconst LABEL_W = 78\nconst CELL_W = 104\n\n// A single chip with a leading status dot. The dot defaults to the chip's own\n// resolved text color, so the indicator stays legible across every variant +\n// scheme without any per-cell color plumbing.\nfunction ChipCell({ variant, color, label }: { variant: NonNullable<ChipProps['variant']>; color: string; label: string }) {\n  return (\n    <Row justify=\"center\" style={{ width: CELL_W }}>\n      <Chip variant={variant} color={color} size=\"sm\" dot>\n        {label}\n      </Chip>\n    </Row>\n  )\n}\n\nfunction Matrix() {\n  return (\n    <Block fullWidth={false}>\n      {/* Column headers */}\n      <Row gap=\"xs\" align=\"center\">\n        <Text style={{ width: LABEL_W }}> </Text>\n        {VARIANTS.map((v) => (\n          <Text\n            key={v}\n            size=\"xs\"\n            color=\"muted\"\n            align=\"center\"\n            style={{ width: CELL_W }}\n          >\n            {v}\n          </Text>\n        ))}\n      </Row>\n\n      {ROWS.map(({ color, label }) => (\n        <Row key={color} gap=\"xs\" align=\"center\">\n          <Text size=\"xs\" color=\"muted\" style={{ width: LABEL_W }}>\n            {label}\n          </Text>\n          {VARIANTS.map((v) => (\n            <ChipCell key={v} variant={v} color={color} label={label} />\n          ))}\n        </Row>\n      ))}\n    </Block>\n  )\n}\n\nfunction Panel({\n  theme,\n  title,\n  surface,\n}: {\n  theme: typeof DEFAULT_THEME\n  title: string\n  surface: string\n}) {\n  return (\n    <PlatformBlocksThemeProvider theme={theme} inherit={false}>\n      <Card\n        withBorder\n        padding=\"lg\"\n        radius=\"lg\"\n        style={{ flexGrow: 1, flexShrink: 1, flexBasis: 380, minWidth: 300 }}\n      >\n        <Block fullWidth>\n          <Row justify=\"space-between\" align=\"baseline\">\n            <Text weight=\"600\">{title}</Text>\n            <Text size=\"xs\" color=\"muted\">\n              {surface}\n            </Text>\n          </Row>\n          <Matrix />\n        </Block>\n      </Card>\n    </PlatformBlocksThemeProvider>\n  )\n}\n\nexport function Demo() {\n  // Two panels, each locked to a scheme, so every variant can be read side by side\n  // on the real light and dark surfaces. Text is resolved by measured contrast, so\n  // every variant stays legible on both.\n  return (\n    <Row gap=\"md\" wrap=\"wrap\" align=\"stretch\">\n      <Panel theme={DEFAULT_THEME} title=\"Light surface\" surface=\"#FFFFFF\" />\n      <Panel theme={DARK_THEME} title=\"Dark surface\" surface=\"#1C1C1E\" />\n    </Row>\n  )\n}\n",hash:"6f854b26297a79db13f56c49430dcb2cb0e3171d2ad52ff40af117fdf99eaee8",importPath:"../../../../packages/ui/src/components/Chip/demos/theme-matrix",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Chip/demos/theme-matrix/index.tsx"},"Chip.variants":{code:"import { Chip, Row } from '@platform-blocks/react-ui-library'\n\nexport function Demo() {\n  return (\n    <Row gap={8} wrap=\"wrap\">\n      <Chip variant=\"filled\" color=\"primary\">\n        Filled\n      </Chip>\n      <Chip variant=\"outline\" color=\"primary\">\n        Outline\n      </Chip>\n      <Chip variant=\"light\" color=\"primary\">\n        Light\n      </Chip>\n      <Chip variant=\"subtle\" color=\"primary\">\n        Subtle\n      </Chip>\n      <Chip variant=\"surface\">\n        Surface\n      </Chip>\n      <Chip variant=\"gradient\" color=\"primary\">\n        Gradient\n      </Chip>\n    </Row>\n  )\n}",hash:"6746ae256d71dadf92dd97180bf0ed915ad4676b075853357e9b9a65289d06a4",importPath:"../../../../packages/ui/src/components/Chip/demos/variants",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Chip/demos/variants/index.tsx"}}},3268,[]);
__d(function(n,e,o,t,l,i,a){l.exports={"CodeBlock.basic":{code:"import { Block, CodeBlock, Text } from '@platform-blocks/react-ui-library';\n\nconst sample = `import { View, Text } from 'react-native';\n\nexport function HelloWorld() {\n  return (\n    <View>\n      <Text>Hello, World!</Text>\n    </View>\n  );\n}`;\n\nexport function Demo() {\n  return (\n    <Block fullWidth>\n      <Text weight=\"semibold\">Basic code block</Text>\n      <Text size=\"sm\" color=\"secondary\">\n        The default CodeBlock renders formatted code with copy support and automatic language detection.\n      </Text>\n      <CodeBlock language=\"tsx\">{sample}</CodeBlock>\n    </Block>\n  );\n}\n",hash:"3e3cc5944ed863d940215c92981c0f02ce56a36728e9208c0f8e0126b2c3c643",importPath:"../../../../packages/ui/src/components/CodeBlock/demos/basic",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/CodeBlock/demos/basic/index.tsx"},"CodeBlock.features":{code:"import { Block, CodeBlock, Text } from '@platform-blocks/react-ui-library';\n\nconst fibonacciExample = `function fibonacci(n) {\n  if (n <= 1) {\n    return n;\n  }\n  return fibonacci(n - 1) + fibonacci(n - 2);\n}\n\n// Calculate the 10th Fibonacci number\nconst result = fibonacci(10);\nconsole.log(\\`Fibonacci(10) = \\${result}\\`);`;\n\nconst fullWidthExample = `// This code block spans the full width of its container\nconst data = [\n  { id: 1, name: 'Alice', age: 30, city: 'New York' },\n  { id: 2, name: 'Bob', age: 25, city: 'San Francisco' },\n  { id: 3, name: 'Charlie', age: 35, city: 'Los Angeles' }\n];\n\nconst processData = (rows) => {\n  return rows\n    .filter((person) => person.age >= 30)\n    .map((person) => ({\n      ...person,\n      isAdult: true,\n      displayName: \\`\\${person.name} (\\${person.age})\\`\n    }))\n    .sort((left, right) => left.name.localeCompare(right.name));\n};\n\nconsole.log(processData(data));`;\n\nconst disabledCopyExample = `// This example has the copy button disabled\nconst message = \"Hello, World!\";\nconsole.log(message);`;\n\nexport function Demo() {\n  return (\n    <Block fullWidth>\n      <Text weight=\"semibold\">Feature highlights</Text>\n      <Text size=\"sm\" color=\"secondary\">\n        Combine titles, line numbers, full-width layouts, and copy controls to match different documentation needs.\n      </Text>\n      <Block>\n        <Block>\n          <Text size=\"sm\" weight=\"semibold\">\n            Title with line numbers\n          </Text>\n          <CodeBlock title=\"With title and line numbers\" showLineNumbers>\n            {fibonacciExample}\n          </CodeBlock>\n        </Block>\n\n        <Block>\n          <Text size=\"sm\" weight=\"semibold\">\n            Full-width layout\n          </Text>\n          <CodeBlock title=\"Full width example\" fullWidth language=\"javascript\">\n            {fullWidthExample}\n          </CodeBlock>\n        </Block>\n\n        <Block>\n          <Text size=\"sm\" weight=\"semibold\">\n            Copy button disabled\n          </Text>\n          <CodeBlock title=\"No copy button\" showCopyButton={false}>\n            {disabledCopyExample}\n          </CodeBlock>\n        </Block>\n      </Block>\n    </Block>\n  );\n}\n",hash:"bfcbc523d8afa7ea2b08c23d41f74d52c96472ee17aca5215a31e65aadc717ae",importPath:"../../../../packages/ui/src/components/CodeBlock/demos/features",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/CodeBlock/demos/features/index.tsx"},"CodeBlock.files":{code:"import { Block, CodeBlock, Text } from '@platform-blocks/react-ui-library';\n\nconst FILES = [\n  {\n    name: 'index.tsx',\n    code: `import { Blockquote } from '@platform-blocks/react-ui-library';\n\nimport { AUTHOR, QUOTE } from './data';\n\nexport function Demo() {\n  return <Blockquote author={AUTHOR}>{QUOTE}</Blockquote>;\n}`,\n  },\n  {\n    name: 'data.ts',\n    code: `export const AUTHOR = {\n  name: 'Priya Shah',\n  title: 'CTO',\n  organization: 'Northwind Labs',\n};\n\nexport const QUOTE = 'The components feel native on every platform.';`,\n  },\n  {\n    name: 'quote.css',\n    code: `.quote {\n  border-left: 4px solid var(--primary-5);\n  padding: 16px 20px;\n}`,\n  },\n  {\n    name: 'theme.json',\n    code: `{\n  \"primaryColor\": \"blue\",\n  \"defaultRadius\": \"md\"\n}`,\n  },\n];\n\nexport function Demo() {\n  return (\n    <Block fullWidth>\n      <Text size=\"sm\" color=\"secondary\">\n        Switch files from the tab strip in the top-left corner.\n      </Text>\n      <CodeBlock files={FILES} />\n    </Block>\n  );\n}\n",hash:"110caf00b6a9745dd245d86a83f2075bdb09da433346cfcb83b72e88a966cd1e",importPath:"../../../../packages/ui/src/components/CodeBlock/demos/files",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/CodeBlock/demos/files/index.tsx"},"CodeBlock.github":{code:"import { Block, CodeBlock, Text } from '@platform-blocks/react-ui-library';\n\nconst componentExample = `import { View, Text } from 'react-native';\n\nexport function HelloWorld() {\n  return (\n    <View>\n      <Text>Hello, World!</Text>\n    </View>\n  );\n}`;\n\nconst inlineExample = `// This code has both copy and GitHub buttons\nexport function MyComponent() {\n  return <div>Hello with GitHub button!</div>;\n}`;\n\nconst terminalExample = `$ npm install platform-blocks\n$ npm start\nServer running on http://localhost:3000`;\n\nconst floatingExample = `// Floating buttons example (no title)\nexport function FloatingExample() {\n  return <span>Hover to see buttons</span>;\n}`;\n\nexport function Demo() {\n  return (\n    <Block fullWidth>\n      <Text weight=\"semibold\">GitHub actions</Text>\n      <Text size=\"sm\" color=\"secondary\">\n        Provide a GitHub URL to render quick links beside copy controls across any CodeBlock variant.\n      </Text>\n      <Block>\n        <Block>\n          <Text size=\"sm\" weight=\"semibold\">\n            Basic component\n          </Text>\n          <CodeBlock\n            title=\"Basic component\"\n            githubUrl=\"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Button/Button.tsx\"\n          >\n            {componentExample}\n          </CodeBlock>\n        </Block>\n\n        <Block>\n          <Text size=\"sm\" weight=\"semibold\">\n            File name and language\n          </Text>\n          <CodeBlock\n            files={[{ name: 'example.tsx' }]}\n            githubUrl=\"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Text/Text.tsx\"\n          >\n            {inlineExample}\n          </CodeBlock>\n        </Block>\n\n        <Block>\n          <Text size=\"sm\" weight=\"semibold\">\n            Terminal variant\n          </Text>\n          <CodeBlock\n            variant=\"terminal\"\n            title=\"Terminal example\"\n            githubUrl=\"https://github.com/platform-blocks/react-ui-library/blob/main/apps/react-ui-library.com/eas-build-post-install.sh\"\n          >\n            {terminalExample}\n          </CodeBlock>\n        </Block>\n\n        <Block>\n          <Text size=\"sm\" weight=\"semibold\">\n            Floating controls\n          </Text>\n          <CodeBlock githubUrl=\"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/CodeBlock/CodeBlock.tsx\">\n            {floatingExample}\n          </CodeBlock>\n        </Block>\n      </Block>\n    </Block>\n  );\n}\n",hash:"7fe0f318dd560911543abd77f766473b6bc53b8a09ff641881d3197ec24c2301",importPath:"../../../../packages/ui/src/components/CodeBlock/demos/github",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/CodeBlock/demos/github/index.tsx"},"CodeBlock.highlighting":{code:"import { Block, CodeBlock, Text } from '@platform-blocks/react-ui-library';\n\nconst sample = `import { View, Text } from 'react-native';\n\ninterface User {\n  id: number;\n  name: string; // highlighted\n  active: boolean;\n}\n\nexport function UserCard({ user }: { user: User }) {\n  if (!user.active) {\n    return null; // early return highlighted\n  }\n  return (\n    <View style={{ padding: 8 }}>\n      <Text>{user.name}</Text>\n    </View>\n  );\n}\n\n// Utility function (range highlighted)\nexport function filterActive(users: User[]) {\n  return users.filter((u) => u.active);\n}`;\n\nexport function Demo() {\n  return (\n    <Block fullWidth>\n      <Text weight=\"semibold\">Highlighted lines</Text>\n      <Text size=\"sm\" color=\"secondary\">\n        Combine individual lines and ranges in the highlightLines prop to emphasize key logic.\n      </Text>\n  <CodeBlock title=\"Highlighted lines\" showLineNumbers highlightLines={['1', '5-9', '11-14', '20-22']}>\n        {sample}\n      </CodeBlock>\n    </Block>\n  );\n}\n",hash:"549cf87b85f35bb11e0c18a81a9a537216189ff0de2e7334deba9ace9f52cb51",importPath:"../../../../packages/ui/src/components/CodeBlock/demos/highlighting",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/CodeBlock/demos/highlighting/index.tsx"},"CodeBlock.interactive":{code:"import { useEffect, useRef, useState } from 'react';\n\nimport { Block, Button, CodeBlock, Text } from '@platform-blocks/react-ui-library';\n\nconst sampleCode = `const greeting = \"Hello, World!\";\nconsole.log(greeting);\n\n// A simple function\nfunction add(a, b) {\n  return a + b;\n}\n\nconst result = add(5, 3);\nconsole.log(\\`5 + 3 = \\${result}\\`);`;\n\nexport function Demo() {\n  const [copiedLength, setCopiedLength] = useState<number | null>(null);\n  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);\n\n  useEffect(() => {\n    return () => {\n      if (timeoutRef.current) {\n        clearTimeout(timeoutRef.current);\n      }\n    };\n  }, []);\n\n  const handleCopy = (code: string) => {\n    if (timeoutRef.current) {\n      clearTimeout(timeoutRef.current);\n    }\n\n    setCopiedLength(code.length);\n    timeoutRef.current = setTimeout(() => {\n      setCopiedLength(null);\n      timeoutRef.current = null;\n    }, 2000);\n  };\n\n  return (\n    <Block fullWidth>\n      <Text weight=\"semibold\">Interactive copy</Text>\n      <Text size=\"sm\" color=\"secondary\">\n        Attach an onCopy handler to trigger custom feedback and reuse it outside the CodeBlock controls.\n      </Text>\n      {copiedLength !== null && (\n        <Text size=\"xs\" color=\"success\">\n          Copied {copiedLength} characters to the clipboard.\n        </Text>\n      )}\n      <CodeBlock language=\"javascript\" title=\"Interactive copy example\" onCopy={handleCopy}>\n        {sampleCode}\n      </CodeBlock>\n      <Button title=\"Copy code manually\" variant=\"outline\" onPress={() => handleCopy(sampleCode)} />\n    </Block>\n  );\n}\n",hash:"b1b60ed7b1dda8c1989fcbbc873e137a5a3e07bca7b9b9a56af0531ad4f12c06",importPath:"../../../../packages/ui/src/components/CodeBlock/demos/interactive",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/CodeBlock/demos/interactive/index.tsx"},"CodeBlock.languages":{code:"import { Block, CodeBlock, Text } from '@platform-blocks/react-ui-library';\n\nconst tsxExample = `interface Props {\n  title: string;\n  onPress?: () => void;\n}\n\nexport function Button({ title, onPress }: Props) {\n  return (\n    <TouchableOpacity onPress={onPress}>\n      <Text>{title}</Text>\n    </TouchableOpacity>\n  );\n}`;\n\nconst jsonExample = `{\n  \"name\": \"my-app\",\n  \"version\": \"1.0.0\",\n  \"dependencies\": {\n    \"react\": \"^18.2.0\",\n    \"react-native\": \"^0.72.0\"\n  },\n  \"scripts\": {\n    \"start\": \"expo start\",\n    \"build\": \"expo build\"\n  }\n}`;\n\nconst markdownExample = `# Getting Started\n\nThis is a **markdown** example with \\`inline code\\`.\n\n## Features\n\n- Syntax highlighting\n- Multiple languages\n- Copy functionality\n\n> Blockquote with *emphasis* and **bold** text.`;\n\nexport function Demo() {\n  return (\n    <Block fullWidth>\n      <Text weight=\"semibold\">Language presets</Text>\n      <Text size=\"sm\" color=\"secondary\">\n        CodeBlock detects syntax styles across languages like TypeScript, JSON, and Markdown.\n      </Text>\n      <Block>\n        <CodeBlock language=\"tsx\" title=\"React component\">\n          {tsxExample}\n        </CodeBlock>\n        <CodeBlock language=\"json\" title=\"Package configuration\">\n          {jsonExample}\n        </CodeBlock>\n        <CodeBlock language=\"markdown\" title=\"Documentation\">\n          {markdownExample}\n        </CodeBlock>\n      </Block>\n    </Block>\n  );\n}\n",hash:"b62c26c384196e1d071083d1cff40249aa31138cd95cff4c191a7f732a5d75b9",importPath:"../../../../packages/ui/src/components/CodeBlock/demos/languages",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/CodeBlock/demos/languages/index.tsx"},"CodeBlock.variants":{code:"import { Block, CodeBlock, Text } from '@platform-blocks/react-ui-library';\n\nconst sampleCode = `function hackTheMatrix() {\n  const matrix = generateMatrix();\n  console.log('Entering the matrix...');\n\n  for (let i = 0; i < matrix.length; i += 1) {\n    matrix[i].decrypt();\n  }\n\n  return 'Welcome to the real world.';\n}`;\n\nconst terminalCode = `$ npm install platform-blocks\n$ cd my-app\n$ npm start\nServer running on port 3000`;\n\nexport function Demo() {\n  return (\n    <Block fullWidth>\n      <Text weight=\"semibold\">Visual variants</Text>\n      <Text size=\"sm\" color=\"secondary\">\n        Switch between default, terminal, and hacker themes using the variant prop.\n      </Text>\n      <Block>\n        <Block>\n          <Text size=\"sm\" weight=\"semibold\">\n            Default code block\n          </Text>\n          <CodeBlock language=\"javascript\" title=\"matrix.js\">\n            {sampleCode}\n          </CodeBlock>\n        </Block>\n\n        <Block>\n          <Text size=\"sm\" weight=\"semibold\">\n            Terminal variant\n          </Text>\n          <CodeBlock variant=\"terminal\" title=\"Terminal\">\n            {terminalCode}\n          </CodeBlock>\n        </Block>\n\n        <Block>\n          <Text size=\"sm\" weight=\"semibold\">\n            Hacker variant\n          </Text>\n          <CodeBlock variant=\"hacker\" language=\"javascript\" title=\"hack.exe\">\n            {sampleCode}\n          </CodeBlock>\n        </Block>\n      </Block>\n    </Block>\n  );\n}",hash:"2fef68a20c7cb046bcd2f1e51f257d1a5098aaf0d87bc610c129eff0bde21d06",importPath:"../../../../packages/ui/src/components/CodeBlock/demos/variants",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/CodeBlock/demos/variants/index.tsx"}}},3269,[]);
