__d(function(n,e,o,t,a,r,i){a.exports={"Markdown.basic":{code:"import { Block, Markdown, Text } from '@platform-blocks/react-ui-library';\n\nconst CONTENT = `# Hello Markdown\n\nThis is a **bold** statement and this is _italic_.\n\n- Item one\n- Item two\n- Item three\n\n> Blockquote with *inline emphasis* and **strong** text.\n\nInline code: \\`const x = 42;\\``;\n\nexport function Demo() {\n  return (\n    <Block fullWidth>\n      <Markdown>{CONTENT}</Markdown>\n      <Text size=\"sm\" color=\"secondary\">\n        Rendered using the default Markdown renderer\n      </Text>\n    </Block>\n  );\n}\n",hash:"c12df7a6322e1615a6e444cc2935df482641a4dc4558c00937c64ae132b2e54d",importPath:"../../../../packages/ui/src/components/Markdown/demos/basic",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Markdown/demos/basic/index.tsx"},"Markdown.code":{code:"import { Block, Markdown, Text } from '@platform-blocks/react-ui-library';\n\nconst CONTENT = `# Code examples\n\nHere's some JavaScript:\n\n\\`\\`\\`javascript\nfunction fibonacci(n) {\n  if (n <= 1) return n;\n  return fibonacci(n - 1) + fibonacci(n - 2);\n}\n\\`\\`\\`\n\nAnd some TypeScript:\n\n\\`\\`\\`typescript\ninterface User {\n  id: number;\n  name: string;\n  email: string;\n}\n\nconst user: User = {\n  id: 1,\n  name: \"John Doe\",\n  email: \"john@example.com\"\n};\n\\`\\`\\`\n\nInline code: \\`const result = fibonacci(10);\\``;\n\nexport function Demo() {\n  return (\n    <Block fullWidth>\n      <Markdown>{CONTENT}</Markdown>\n      <Text size=\"sm\" color=\"secondary\">\n        Showcases fenced code blocks with syntax highlighting\n      </Text>\n    </Block>\n  );\n}\n",hash:"87fa9b2fa0bd1a7db4885309baa00dd4d7c1c11de0bb58369646773ae0ccf05b",importPath:"../../../../packages/ui/src/components/Markdown/demos/code",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Markdown/demos/code/index.tsx"},"Markdown.custom":{code:"import { Block, Card, Markdown, Text } from '@platform-blocks/react-ui-library';\n\nconst CUSTOM_COMPONENTS = {\n  h1: ({ children, ...props }: any) => (\n    <Text size=\"xl\" weight=\"bold\" color=\"primary\" mb={12} {...props}>\n      {children}\n    </Text>\n  ),\n  h2: ({ children, ...props }: any) => (\n    <Text size=\"lg\" weight=\"semibold\" color=\"accent\" mb={8} {...props}>\n      {children}\n    </Text>\n  ),\n  p: ({ children, ...props }: any) => (\n    <Text size=\"md\" mb={8} {...props}>\n      {children}\n    </Text>\n  ),\n  blockquote: ({ children, ...props }: any) => (\n    <Card p={12} variant=\"outline\" bg=\"muted\" mb={8} {...props}>\n      <Text size=\"sm\" style={{ fontStyle: 'italic' }}>\n        {children}\n      </Text>\n    </Card>\n  ),\n};\n\nconst CONTENT = `# Custom styled Markdown\n\n## This is a subtitle\n\nThis paragraph uses custom styling and components.\n\n> This blockquote is rendered with a custom Card component and muted background.\n\nRegular paragraph text with default styling.\n`;\n\nexport function Demo() {\n  return (\n    <Block fullWidth>\n      <Markdown components={CUSTOM_COMPONENTS}>{CONTENT}</Markdown>\n      <Text size=\"sm\" color=\"secondary\">\n        Headings, paragraphs, and quotes use custom renderers\n      </Text>\n    </Block>\n  );\n}\n",hash:"40e8072ca68715019bb77a07f2c4ddb6b2963a49d9107a4d7a9020301537e954",importPath:"../../../../packages/ui/src/components/Markdown/demos/custom",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Markdown/demos/custom/index.tsx"},"Markdown.inline":{code:"import { Block, Markdown, Text } from '@platform-blocks/react-ui-library';\n\nexport function Demo() {\n  const inlineContent = 'This is **bold text** and this is *italic text* with `inline code`.';\n\n  return (\n    <Block fullWidth>\n      <Text size=\"md\" as=\"div\">\n        Inline markdown: <Markdown>{inlineContent}</Markdown>\n      </Text>\n\n      <Text size=\"md\" as=\"div\">\n        Mix with regular text: Here's some regular text, then <Markdown>**markdown formatting**</Markdown> and\n        back to regular.\n      </Text>\n\n      <Text size=\"md\" as=\"div\">\n        Code in context: Use <Markdown>`const x = 42;`</Markdown> to declare a variable.\n      </Text>\n    </Block>\n  );\n}\n",hash:"f2ea9c41287eb9b486f48adccc9d4f89ab18c9ce23f9b739f70095d7f98bfebf",importPath:"../../../../packages/ui/src/components/Markdown/demos/inline",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Markdown/demos/inline/index.tsx"},"Markdown.media":{code:"import { Block, Markdown, Text } from '@platform-blocks/react-ui-library';\n\nconst CONTENT = `# Media in Markdown\n\n## Images\n\n![PlatformBlocks Logo](https://raw.githubusercontent.com/platform-blocks/react-ui-library/main/apps/react-ui-library.com/assets/favicon.png)\n\n## Links\n\nVisit the [PlatformBlocks Documentation](https://react-ui-library.com) for more examples.\n\n## Tables\n\n| Feature | Status | Notes |\n|---------|--------|-------|\n| **Text Formatting** | \u2705 | Bold, _italic_, \\`code\\` |\n| Code Blocks | \u2705 | Syntax highlighting |\n| Tables | \u2705 | Responsive layout |\n| Images | \u2705 | Auto-sizing |\n| [Links](https://react-ui-library.com) | \u2705 | External navigation |\n\n## Horizontal Rule\n\nContent above the line.\n\n---\n\nContent below the line.`;\n\nexport function Demo() {\n  return (\n    <Block fullWidth>\n      <Markdown>{CONTENT}</Markdown>\n      <Text size=\"sm\" color=\"secondary\">\n        Images, links, tables, and horizontal rules render inline\n      </Text>\n    </Block>\n  );\n}\n",hash:"4381427f57a8b0f4cfd286b03cb5199cf61c90f45e5197b41d0049c66a629caa",importPath:"../../../../packages/ui/src/components/Markdown/demos/media",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Markdown/demos/media/index.tsx"},"Markdown.table":{code:"import { Block, Markdown, Text } from '@platform-blocks/react-ui-library';\n\nconst CONTENT = `# Table examples\n\n## Basic table\n\n| Name | Age | City |\n|------|-----|------|\n| John Doe | 30 | New York |\n| Jane Smith | 25 | Los Angeles |\n| Bob Johnson | 35 | Chicago |\n\n## Table with formatting\n\n| Feature | Status | **Priority** | Notes |\n|---------|--------|-------------|--------|\n| Authentication | \u2705 | **High** | _Complete_ |\n| User Management | \ud83d\udd04 | **Medium** | In progress |\n| Analytics | \u274c | **Low** | \\`Not started\\` |\n| API Integration | \u2705 | **High** | [Documentation](https://example.com) |\n\n## Table with code\n\n| Language | Extension | Sample code |\n|----------|-----------|-------------|\n| TypeScript | \\`.tsx\\` | \\`const x: string = \"hello\";\\` |\n| JavaScript | \\`.js\\` | \\`function hello() { return \"world\"; }\\` |\n| Python | \\`.py\\` | \\`def hello(): return \"world\"\\` |\n\n## Complex table\n\n| Component | **Props** | _Description_ | Example |\n|-----------|----------|-------------|---------|\n| Button | \\`variant\\`, \\`size\\`, \\`disabled\\` | Interactive button element | \\`<Button variant=\"filled\">Click me</Button>\\` |\n| Input | \\`placeholder\\`, \\`value\\`, \\`onChange\\` | Text input field | \\`<Input placeholder=\"Enter text\" />\\` |\n| Card | \\`variant\\`, \\`padding\\` | Container component | \\`<Card variant=\"outline\">Content</Card>\\` |`;\n\nexport function Demo() {\n  return (\n    <Block fullWidth>\n      <Markdown>{CONTENT}</Markdown>\n      <Text size=\"sm\" color=\"secondary\">\n        Multiple table layouts rendered with Markdown\n      </Text>\n    </Block>\n  );\n}\n",hash:"1e1b6bf5974519d046d80e65e457f7128bf0823198cb211a5817f06eaa4ba6ea",importPath:"../../../../packages/ui/src/components/Markdown/demos/table",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Markdown/demos/table/index.tsx"}}},3311,[]);
__d(function(n,t,e,a,o,r,i){o.exports={"Masonry.basic":{code:"import { Masonry, Card, Text, useTheme } from '@platform-blocks/react-ui-library';\nimport type { MasonryItem } from '@platform-blocks/react-ui-library';\n\nexport function Demo() {\n  const theme = useTheme();\n  \n  const masonryItems: MasonryItem[] = [\n    {\n      id: '1',\n      content: (\n        <Card p={16}>\n          <Text variant=\"strong\" style={{ marginBottom: 8 }}>Card 1</Text>\n          <Text>This is a basic card item in the masonry layout.</Text>\n        </Card>\n      ),\n    },\n    {\n      id: '2',\n      content: (\n        <Card p={16}>\n          <Text variant=\"strong\" style={{ marginBottom: 8 }}>Card 2</Text>\n          <Text>Short content.</Text>\n        </Card>\n      ),\n    },\n    {\n      id: '3',\n      content: (\n        <Card p={16}>\n          <Text variant=\"strong\" style={{ marginBottom: 8 }}>Card 3</Text>\n          <Text>A third card showing how items are arranged in the masonry grid with longer content that will make this card taller than the others.</Text>\n        </Card>\n      ),\n    },\n    {\n      id: '4',\n      content: (\n        <Card p={16}>\n          <Text variant=\"strong\" style={{ marginBottom: 8 }}>Card 4</Text>\n          <Text>Medium length content here.</Text>\n        </Card>\n      ),\n    },\n    {\n      id: '5',\n      content: (\n        <Card p={16}>\n          <Text variant=\"strong\" style={{ marginBottom: 8 }}>Card 5</Text>\n          <Text>Fifth card in the masonry layout grid.</Text>\n        </Card>\n      ),\n    },\n    {\n      id: '6',\n      content: (\n        <Card p={16}>\n          <Text variant=\"strong\" style={{ marginBottom: 8 }}>Card 6</Text>\n          <Text>Sixth card showing the two-column arrangement.</Text>\n        </Card>\n      ),\n    },\n  ];\n\n  return (\n    <Masonry\n      data={masonryItems}\n      numColumns={2}\n      gap=\"md\"\n      style={{ height: 400 }}\n    />\n  );\n}",hash:"63f97073eeabc9d954d988863dca1db542b7d7131a6f9bf04c3fa1dff6399fe1",importPath:"../../../../packages/ui/src/components/Masonry/demos/basic",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Masonry/demos/basic/index.tsx"},"Masonry.custom-columns":{code:"import { Masonry, Card, Text, Button, Row, useTheme } from '@platform-blocks/react-ui-library';\nimport type { MasonryItem } from '@platform-blocks/react-ui-library';\nimport { useState } from 'react';\n\nexport function Demo() {\n  const theme = useTheme();\n  const [numColumns, setNumColumns] = useState(3);\n  \n  const masonryItems: MasonryItem[] = [\n    {\n      id: '1',\n      heightRatio: 1.1,\n      content: (\n        <Card p={12}>\n          <Text variant=\"strong\" style={{ marginBottom: 6 }}>Item 1</Text>\n          <Text>Content for first item with some extra text.</Text>\n        </Card>\n      ),\n    },\n    {\n      id: '2',\n      heightRatio: 0.8,\n      content: (\n        <Card p={12}>\n          <Text variant=\"strong\" style={{ marginBottom: 6 }}>Item 2</Text>\n          <Text>Short content.</Text>\n        </Card>\n      ),\n    },\n    {\n      id: '3',\n      heightRatio: 1.3,\n      content: (\n        <Card p={12}>\n          <Text variant=\"strong\" style={{ marginBottom: 6 }}>Item 3</Text>\n          <Text>Longer content to demonstrate height variation in different column layouts.</Text>\n        </Card>\n      ),\n    },\n    {\n      id: '4',\n      heightRatio: 0.9,\n      content: (\n        <Card p={12}>\n          <Text variant=\"strong\" style={{ marginBottom: 6 }}>Item 4</Text>\n          <Text>Medium length content.</Text>\n        </Card>\n      ),\n    },\n    {\n      id: '5',\n      heightRatio: 1.5,\n      content: (\n        <Card p={12}>\n          <Text variant=\"strong\" style={{ marginBottom: 6 }}>Item 5</Text>\n          <Text>Extended content that takes up more space to show how columns adapt.</Text>\n        </Card>\n      ),\n    },\n    {\n      id: '6',\n      heightRatio: 0.7,\n      content: (\n        <Card p={12}>\n          <Text variant=\"strong\" style={{ marginBottom: 6 }}>Item 6</Text>\n          <Text>Compact.</Text>\n        </Card>\n      ),\n    },\n    {\n      id: '7',\n      heightRatio: 1.2,\n      content: (\n        <Card p={12}>\n          <Text variant=\"strong\" style={{ marginBottom: 6 }}>Item 7</Text>\n          <Text>Another item with moderate content length for testing.</Text>\n        </Card>\n      ),\n    },\n    {\n      id: '8',\n      heightRatio: 0.9,\n      content: (\n        <Card p={12}>\n          <Text variant=\"strong\" style={{ marginBottom: 6 }}>Item 8</Text>\n          <Text>Standard content item.</Text>\n        </Card>\n      ),\n    },\n    {\n      id: '9',\n      heightRatio: 1.4,\n      content: (\n        <Card p={12}>\n          <Text variant=\"strong\" style={{ marginBottom: 6 }}>Item 9</Text>\n          <Text>Taller content to fill out the grid and show column distribution effects.</Text>\n        </Card>\n      ),\n    },\n  ];\n\n  return (\n    <>\n      <Row gap=\"sm\" style={{ marginBottom: 16 }}>\n        <Button\n          title=\"1 Column\"\n          size=\"sm\"\n          variant={numColumns === 1 ? 'filled' : 'outline'}\n          onPress={() => setNumColumns(1)}\n        />\n        <Button\n          title=\"2 Columns\"\n          size=\"sm\"\n          variant={numColumns === 2 ? 'filled' : 'outline'}\n          onPress={() => setNumColumns(2)}\n        />\n        <Button\n          title=\"3 Columns\"\n          size=\"sm\"\n          variant={numColumns === 3 ? 'filled' : 'outline'}\n          onPress={() => setNumColumns(3)}\n        />\n        <Button\n          title=\"4 Columns\"\n          size=\"sm\"\n          variant={numColumns === 4 ? 'filled' : 'outline'}\n          onPress={() => setNumColumns(4)}\n        />\n      </Row>\n\n      <Masonry\n        data={masonryItems}\n        numColumns={numColumns}\n        gap=\"md\"\n        style={{ height: 400 }}\n      />\n    </>\n  );\n}",hash:"aae90bfec5c5aa213e011ab11c59b61011f9e8b6acd234588b860aeb37826217",importPath:"../../../../packages/ui/src/components/Masonry/demos/custom-columns",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Masonry/demos/custom-columns/index.tsx"},"Masonry.variable-heights":{code:"import { Masonry, Card, Text, useTheme } from '@platform-blocks/react-ui-library';\nimport type { MasonryItem } from '@platform-blocks/react-ui-library';\n\nexport function Demo() {\n  const theme = useTheme();\n  \n  const masonryItems: MasonryItem[] = [\n    {\n      id: '1',\n      heightRatio: 1.2,\n      content: (\n        <Card p={16}>\n          <Text variant=\"strong\" style={{ marginBottom: 8 }}>Tall Card</Text>\n          <Text>\n            This is a taller card with more content to demonstrate the variable height \n            functionality. It shows how items with different heights are arranged in \n            the masonry layout to create an organic, staggered appearance.\n          </Text>\n        </Card>\n      ),\n    },\n    {\n      id: '2',\n      heightRatio: 0.7,\n      content: (\n        <Card p={16}>\n          <Text variant=\"strong\" style={{ marginBottom: 8 }}>Short Card</Text>\n          <Text>A shorter card with minimal content.</Text>\n        </Card>\n      ),\n    },\n    {\n      id: '3',\n      heightRatio: 1.8,\n      content: (\n        <Card p={16}>\n          <Text variant=\"strong\" style={{ marginBottom: 8 }}>Very Tall Card</Text>\n          <Text>\n            This card is extra tall to showcase the masonry layout's ability to handle \n            significant height variations. Lorem ipsum dolor sit amet, consectetur \n            adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna \n            aliqua. Ut enim ad minim veniam, quis nostrud exercitation.\n          </Text>\n          <Text style={{ marginTop: 8 }}>\n            Additional paragraph to make it even taller and show how the layout adapts \n            to content of different sizes naturally.\n          </Text>\n        </Card>\n      ),\n    },\n    {\n      id: '4',\n      heightRatio: 1.0,\n      content: (\n        <Card p={16}>\n          <Text variant=\"strong\" style={{ marginBottom: 8 }}>Regular Card</Text>\n          <Text>A standard height card with regular content length.</Text>\n        </Card>\n      ),\n    },\n    {\n      id: '5',\n      heightRatio: 0.9,\n      content: (\n        <Card p={16}>\n          <Text variant=\"strong\" style={{ marginBottom: 8 }}>Medium Card</Text>\n          <Text>Medium height card with moderate content.</Text>\n        </Card>\n      ),\n    },\n    {\n      id: '6',\n      heightRatio: 1.5,\n      content: (\n        <Card p={16}>\n          <Text variant=\"strong\" style={{ marginBottom: 8 }}>Extended Card</Text>\n          <Text>\n            An extended card that demonstrates how the masonry layout handles \n            items that are taller than average, creating natural flow patterns.\n          </Text>\n        </Card>\n      ),\n    },\n    {\n      id: '7',\n      heightRatio: 0.6,\n      content: (\n        <Card p={16}>\n          <Text variant=\"strong\" style={{ marginBottom: 8 }}>Compact</Text>\n          <Text>Compact card.</Text>\n        </Card>\n      ),\n    },\n    {\n      id: '8',\n      heightRatio: 2.0,\n      content: (\n        <Card p={16}>\n          <Text variant=\"strong\" style={{ marginBottom: 8 }}>Extra Tall Card</Text>\n          <Text>\n            This is the tallest card in the set, demonstrating the maximum height \n            variation supported by the masonry layout. It shows how very tall items \n            are positioned while maintaining good visual balance.\n          </Text>\n          <Text style={{ marginTop: 8 }}>\n            The masonry layout algorithm ensures that even with extreme height \n            differences, the overall composition remains visually pleasing and \n            well-balanced across columns.\n          </Text>\n          <Text style={{ marginTop: 8 }}>\n            This extra content makes the card significantly taller than others to \n            really showcase the variable height capabilities.\n          </Text>\n        </Card>\n      ),\n    },\n  ];\n\n  return (\n    <Masonry\n      data={masonryItems}\n      numColumns={2}\n      gap=\"lg\"\n      optimizeItemArrangement={true}\n      style={{ height: 600 }}\n    />\n  );\n}",hash:"2f34e2c9080ede96d7059199662b91224f6b12292f482bc38ea84e86e5bd45c9",importPath:"../../../../packages/ui/src/components/Masonry/demos/variable-heights",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Masonry/demos/variable-heights/index.tsx"}}},3312,[]);
