__d(function(e,t,n,a,s,o,c){s.exports={"MiniCalendar.basic":{code:"import { useState } from 'react';\nimport { Block, MiniCalendar, Text } from '@platform-blocks/react-ui-library';\n\nexport function Demo() {\n  const [selectedDate, setSelectedDate] = useState<Date | null>(new Date());\n\n  return (\n    <Block fullWidth>\n      <MiniCalendar\n        value={selectedDate}\n        onChange={(date: Date | null) => setSelectedDate(date)}\n        numberOfDays={7}\n      />\n      <Text size=\"sm\" color=\"secondary\">\n        {selectedDate ? `Selected: ${selectedDate.toLocaleDateString()}` : 'No date selected'}\n      </Text>\n    </Block>\n  );\n}\n",hash:"4c0295cc9791428911d1cf5e62990fd781054dcaf81f5138c7ee561cb48dc5be",importPath:"../../../../packages/ui/src/components/MiniCalendar/demos/basic",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/MiniCalendar/demos/basic/index.tsx"},"MiniCalendar.constrained":{code:"import React, { useMemo, useState } from 'react';\nimport { Block, MiniCalendar, Text } from '@platform-blocks/react-ui-library';\n\nexport function Demo() {\n  const [selectedDate, setSelectedDate] = useState<Date | null>(new Date());\n\n  const { minDate, maxDate } = useMemo(() => {\n    const today = new Date();\n    const nextWeek = new Date();\n    nextWeek.setDate(today.getDate() + 7);\n    return { minDate: today, maxDate: nextWeek };\n  }, []);\n\n  return (\n    <Block fullWidth>\n      <MiniCalendar\n        value={selectedDate}\n        onChange={(date: Date | null) => setSelectedDate(date)}\n        numberOfDays={7}\n        minDate={minDate}\n        maxDate={maxDate}\n      />\n      <Text size=\"sm\" color=\"secondary\">\n        {selectedDate ? `Selected: ${selectedDate.toLocaleDateString()}` : 'No date selected'}\n      </Text>\n      <Text size=\"xs\" color=\"secondary\">\n        Only the next seven days are enabled\n      </Text>\n    </Block>\n  );\n}",hash:"f11622824aeda84707cda51aae246b9ccbc522409b7c976707728a44ad13b913",importPath:"../../../../packages/ui/src/components/MiniCalendar/demos/constrained",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/MiniCalendar/demos/constrained/index.tsx"},"MiniCalendar.customDays":{code:"import React, { useState } from 'react';\nimport { Block, Button, MiniCalendar, Row, Text } from '@platform-blocks/react-ui-library';\n\nconst DAY_OPTIONS = [3, 5, 7];\n\nexport function Demo() {\n  const [selectedDate, setSelectedDate] = useState<Date | null>(new Date());\n  const [numberOfDays, setNumberOfDays] = useState(5);\n\n  return (\n    <Block fullWidth>\n      <Row gap=\"xs\">\n        {DAY_OPTIONS.map((days) => (\n          <Button\n            key={days}\n            size=\"sm\"\n            variant={numberOfDays === days ? 'filled' : 'outline'}\n            onPress={() => setNumberOfDays(days)}\n          >\n            {days} days\n          </Button>\n        ))}\n      </Row>\n      <MiniCalendar\n        value={selectedDate}\n        onChange={(date: Date | null) => setSelectedDate(date)}\n        numberOfDays={numberOfDays}\n      />\n      <Text size=\"sm\" color=\"secondary\">\n        {selectedDate ? `Selected: ${selectedDate.toLocaleDateString()}` : 'No date selected'}\n      </Text>\n    </Block>\n  );\n}",hash:"bbdad5f13e4bbd26fd949030fb1e4f7df67db8b20abd06cf7aa9e8a9bb2e827b",importPath:"../../../../packages/ui/src/components/MiniCalendar/demos/customDays",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/MiniCalendar/demos/customDays/index.tsx"}}},3315,[]);
