__d(function(e,n,t,o,a,r,s){a.exports={"NavTree.basic":{code:"import React, { useState } from 'react';\nimport { NavTree, type NavTreeItem } from '@platform-blocks/react-ui-library';\n\n// The whole input: a flat list, with a category on each row. Nothing here\n// describes the tree \u2014 `NavTree` derives it.\nconst ROUTES: NavTreeItem[] = [\n  { label: 'Getting Started', href: '/getting-started' },\n  { label: 'Button', href: '/components/Button', group: ['Components', 'Input'] },\n  { label: 'Select', href: '/components/Select', group: ['Components', 'Input'] },\n  { label: 'Checkbox', href: '/components/Checkbox', group: ['Components', 'Input'] },\n  { label: 'Card', href: '/components/Card', group: ['Components', 'Display'] },\n  { label: 'Badge', href: '/components/Badge', group: ['Components', 'Display'] },\n  { label: 'Tabs', href: '/components/Tabs', group: ['Components', 'Navigation'] },\n];\n\nexport function Demo() {\n  const [route, setRoute] = useState('/components/Select');\n\n  return (\n    <NavTree\n      items={ROUTES}\n      activeHref={route}\n      onNavigate={item => setRoute(item.href)}\n      showGuides\n    />\n  );\n}\n",hash:"5a4498b86c1a09421e7f57f6d50aaeedd9494b10127b77416160a0179558d49c",importPath:"../../../../packages/ui/src/components/NavTree/demos/basic",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/NavTree/demos/basic/index.tsx"},"NavTree.collapsed":{code:"import React, { useState } from 'react';\nimport { Column, Icon, NavTree, Switch, type NavTreeItem } from '@platform-blocks/react-ui-library';\n\nconst ROUTES: NavTreeItem[] = [\n  { label: 'Button', href: '/components/Button', group: 'Components' },\n  { label: 'Card', href: '/components/Card', group: 'Components' },\n  { label: 'LineChart', href: '/components/LineChart', group: 'Charts' },\n  { label: 'BarChart', href: '/components/BarChart', group: 'Charts' },\n  { label: 'useHover', href: '/hooks/useHover', group: 'Hooks' },\n];\n\nconst GROUP_ICONS = {\n  Components: <Icon name=\"grid\" size={18} />,\n  Charts: <Icon name=\"chart-bar\" size={18} />,\n  Hooks: <Icon name=\"hook\" size={18} />,\n};\n\nexport function Demo() {\n  const [collapsed, setCollapsed] = useState(true);\n  const [route, setRoute] = useState('/components/Card');\n\n  return (\n    <Column gap=\"md\">\n      <Switch checked={collapsed} onChange={setCollapsed} label=\"Collapsed\" />\n      <NavTree\n        items={ROUTES}\n        activeHref={route}\n        onNavigate={item => setRoute(item.href)}\n        groupIcons={GROUP_ICONS}\n        collapsed={collapsed}\n      />\n    </Column>\n  );\n}\n",hash:"84a0a0f61716c03c7ab847fe7339c5ab619d7bf565013eaebfb48f375d5b3bcb",importPath:"../../../../packages/ui/src/components/NavTree/demos/collapsed",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/NavTree/demos/collapsed/index.tsx"},"NavTree.counts":{code:"import React, { useState } from 'react';\nimport { Badge, NavTree, type NavTreeItem } from '@platform-blocks/react-ui-library';\n\nconst ROUTES: NavTreeItem[] = [\n  { label: 'Button', href: '/components/Button', group: 'Input' },\n  { label: 'Select', href: '/components/Select', group: 'Input' },\n  { label: 'Checkbox', href: '/components/Checkbox', group: 'Input' },\n  { label: 'Card', href: '/components/Card', group: 'Display' },\n  { label: 'Badge', href: '/components/Badge', group: 'Display' },\n  { label: 'Tabs', href: '/components/Tabs', group: 'Navigation' },\n];\n\nexport function Demo() {\n  const [route, setRoute] = useState('/components/Card');\n\n  return (\n    <NavTree\n      items={ROUTES}\n      activeHref={route}\n      onNavigate={item => setRoute(item.href)}\n      // Curate the order that matters and let the rest sort themselves.\n      groupOrder={['Input', 'Display']}\n      openDepth={0}\n      renderEndSection={node =>\n        node.children ? <Badge size=\"xs\" variant=\"light\">{node.children.length}</Badge> : null\n      }\n    />\n  );\n}\n",hash:"c994e2f04fe9c7915b011b7d1cf007c8850b7e5970853cf7d79b275cc1c8d2f2",importPath:"../../../../packages/ui/src/components/NavTree/demos/counts",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/NavTree/demos/counts/index.tsx"},"NavTree.search":{code:"import React, { useState } from 'react';\nimport { NavTree, type NavTreeItem } from '@platform-blocks/react-ui-library';\n\nconst ROUTES: NavTreeItem[] = [\n  { label: 'Button', href: '/components/Button', group: 'Input' },\n  { label: 'Checkbox', href: '/components/Checkbox', group: 'Input' },\n  { label: 'Select', href: '/components/Select', group: 'Input' },\n  { label: 'TextArea', href: '/components/TextArea', group: 'Input' },\n  { label: 'Badge', href: '/components/Badge', group: 'Display' },\n  { label: 'Card', href: '/components/Card', group: 'Display' },\n  { label: 'Breadcrumbs', href: '/components/Breadcrumbs', group: 'Navigation' },\n  { label: 'Tabs', href: '/components/Tabs', group: 'Navigation' },\n];\n\nexport function Demo() {\n  const [route, setRoute] = useState('/components/Card');\n\n  return (\n    <NavTree\n      items={ROUTES}\n      activeHref={route}\n      onNavigate={item => setRoute(item.href)}\n      searchable\n      searchPlaceholder=\"Filter components\u2026\"\n    />\n  );\n}\n",hash:"5568e43a7544b8ced68edbcee77e10b47d19e75903c5a289e255e3268b1d8f78",importPath:"../../../../packages/ui/src/components/NavTree/demos/search",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/NavTree/demos/search/index.tsx"}}},3318,[]);
