__d(function(e,n,t,a,o,r,i){o.exports={"ShimmerText.basic":{code:"import { Block, ShimmerText } from '@platform-blocks/react-ui-library';\n\nexport function Demo() {\n  return (\n    <Block align=\"flex-start\">\n      <ShimmerText size=\"xl\" weight=\"bold\">\n        Weekly highlights go live\n      </ShimmerText>\n      <ShimmerText>\n        New arrivals shimmer into view every Friday at noon.\n      </ShimmerText>\n    </Block>\n  );\n}",hash:"bc99e5260a23e629099ed0413282fb50a49e7f4a582243a2497c1ae04958ca21",importPath:"../../../../packages/ui/src/components/ShimmerText/demos/basic",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/ShimmerText/demos/basic/index.tsx"},"ShimmerText.controls":{code:"import { useState } from 'react';\nimport { Block, Row, ShimmerText, Slider, Switch, Text } from '@platform-blocks/react-ui-library';\n\nconst MIN_SPREAD = 1;\nconst MAX_SPREAD = 4;\nconst SPREAD_STEP = 0.1;\n\nexport function Demo() {\n  const [spread, setSpread] = useState(2);\n  const [repeat, setRepeat] = useState(true);\n  const [once, setOnce] = useState(false);\n\n  const handleRepeatChange = (value: boolean) => {\n    setRepeat(value);\n    if (value) {\n      setOnce(false);\n    }\n  };\n\n  const handleOnceChange = (value: boolean) => {\n    setOnce(value);\n    if (value) {\n      setRepeat(false);\n    }\n  };\n\n  return (\n    <Block align=\"flex-start\" fullWidth>\n      <ShimmerText\n        spread={spread}\n        repeat={repeat}\n        once={once}\n        repeatDelay={0.6}\n        duration={1.6}\n        shimmerColor=\"#38bdf8\"\n        weight=\"bold\"\n        size=\"lg\"\n      >\n        Interactive shimmer headline\n      </ShimmerText>\n\n      <Block w=\"100%\">\n        <Text variant=\"small\" weight=\"medium\">\n          Spread: {spread.toFixed(1)}\n        </Text>\n        <Slider\n          value={spread}\n          onChange={setSpread}\n          min={MIN_SPREAD}\n          max={MAX_SPREAD}\n          step={SPREAD_STEP}\n        />\n      </Block>\n\n      <Block w=\"100%\">\n        <Row align=\"center\" justify=\"space-between\">\n          <Text variant=\"small\">Repeat animation</Text>\n          <Switch checked={repeat} onChange={handleRepeatChange} />\n        </Row>\n        <Row align=\"center\" justify=\"space-between\">\n          <Text variant=\"small\">Run once</Text>\n          <Switch checked={once} onChange={handleOnceChange} />\n        </Row>\n      </Block>\n    </Block>\n  );\n}\n",hash:"94bf698d685fc941a85136b52588ec4de041b0bbefc8ebf3edbbecb289141ada",importPath:"../../../../packages/ui/src/components/ShimmerText/demos/controls",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/ShimmerText/demos/controls/index.tsx"},"ShimmerText.customization":{code:"import { Block, ShimmerText } from '@platform-blocks/react-ui-library';\n\nexport function Demo() {\n  return (\n    <Block align=\"flex-start\">\n      <ShimmerText shimmerColor=\"#facc15\" spread={3} weight=\"bold\" size=\"xl\">\n        Golden spotlight offer\n      </ShimmerText>\n      <ShimmerText\n        color=\"#475569\"\n        shimmerColor=\"#38bdf8\"\n        spread={1.2}\n        duration={1.2}\n        repeatDelay={0.2}\n      >\n        Fast pulse notification\n      </ShimmerText>\n      <ShimmerText direction=\"rtl\" repeatDelay={0.8}>\n        Shimmer sweeps from right to left\n      </ShimmerText>\n      <ShimmerText once repeat={false} delay={0.5}>\n        Single pass announcement\n      </ShimmerText>\n    </Block>\n  );\n}\n",hash:"3c5947476b26134653374433fcd5a9f81bd1e5d440e2f48a11f1fdaec53c5afc",importPath:"../../../../packages/ui/src/components/ShimmerText/demos/customization",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/ShimmerText/demos/customization/index.tsx"}}},3342,[]);
