__d(function(e,n,t,a,o,c,r){o.exports={"Switch.basic":{code:"import { useState } from 'react';\nimport { Block, Switch, Text } from '@platform-blocks/react-ui-library';\n\nexport function Demo() {\n  const [enabled, setEnabled] = useState<boolean>(true);\n\n  return (\n    <Block>\n      <Switch\n        checked={enabled}\n        onChange={setEnabled}\n        label=\"Enable live score alerts\"\n        description=\"Send push notifications when the match score changes.\"\n      />\n      <Text variant=\"small\" color=\"muted\">\n        Notices are {enabled ? 'enabled' : 'disabled'}.\n      </Text>\n    </Block>\n  );\n}",hash:"97e76d9350a12e26adb2c37205adaa21640828ce92f8c9d3f8ed294e588ac3ae",importPath:"../../../../packages/ui/src/components/Switch/demos/basic",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Switch/demos/basic/index.tsx"},"Switch.colors":{code:"import { Block, Row, Switch, Text } from '@platform-blocks/react-ui-library';\n\nconst COLOR_VARIANTS = [\n  { label: 'Primary', color: 'primary' },\n  { label: 'Secondary', color: 'secondary' },\n  { label: 'Success', color: 'success' },\n  { label: 'Warning', color: 'warning' },\n  { label: 'Error', color: 'error' }\n] as const;\n\nexport function Demo() {\n  return (\n    <Block>\n      <Text variant=\"small\" color=\"muted\">\n        Semantic color variants\n      </Text>\n      <Row gap=\"md\" wrap=\"wrap\">\n        {COLOR_VARIANTS.map(({ label, color }) => (\n          <Switch key={color} defaultChecked label={label} labelPosition=\"right\" color={color} />\n        ))}\n      </Row>\n    </Block>\n  );\n}\n\n\n",hash:"4c8d71fd18d00447e6c8637d9d4c643b22ca6cc9b3d52c7ad8abc92e3d506b81",importPath:"../../../../packages/ui/src/components/Switch/demos/colors",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Switch/demos/colors/index.tsx"},"Switch.sizes":{code:"import { Block, Row, Switch, Text } from '@platform-blocks/react-ui-library';\n\nconst SIZES = ['xs', 'sm', 'md', 'lg', 'xl', '2xl', '3xl'] as const;\n\nexport function Demo() {\n  return (\n    <Row align=\"center\" gap=\"lg\" wrap=\"wrap\">\n      {SIZES.map((size) => (\n        <Block key={size} align=\"center\">\n          <Switch size={size} defaultChecked />\n          <Text variant=\"small\">{size}</Text>\n        </Block>\n      ))}\n    </Row>\n  );\n}\n",hash:"5c7e675be192e88186fb664bfda7529649ebc39e16cb8bbc8c78cf29dd560503",importPath:"../../../../packages/ui/src/components/Switch/demos/sizes",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Switch/demos/sizes/index.tsx"},"Switch.states":{code:"import { useState } from 'react';\nimport { Block, Switch, Text } from '@platform-blocks/react-ui-library';\n\nexport function Demo() {\n  const [homeAlerts, setHomeAlerts] = useState(true);\n  const [awayAlerts, setAwayAlerts] = useState(false);\n\n  return (\n    <Block>\n      <Block>\n        <Text variant=\"small\" color=\"muted\">\n          Interactive states\n        </Text>\n        <Switch\n          checked={homeAlerts}\n          onChange={setHomeAlerts}\n          label=\"Home team alerts\"\n        />\n        <Switch\n          checked={awayAlerts}\n          onChange={setAwayAlerts}\n          label=\"Away team alerts\"\n        />\n      </Block>\n      <Block>\n        <Text variant=\"small\" color=\"muted\">\n          Disabled states\n        </Text>\n        <Switch defaultChecked label=\"Lineup lock\" disabled />\n        <Switch label=\"Sound effects\" disabled />\n      </Block>\n      <Block>\n        <Text variant=\"small\" color=\"muted\">\n          Validation helpers\n        </Text>\n        <Switch\n          label=\"Require broadcast approval\"\n          required\n          error=\"Approval is needed before publishing.\"\n        />\n        <Switch\n          defaultChecked\n          label=\"Send pre-game summary\"\n          description=\"Dispatch an email recap to coaches and analysts.\"\n        />\n      </Block>\n    </Block>\n  );\n}\n",hash:"5756f05c250a4c6c20ceb3b2416e3cf7f4f0a103ff2703c1688a72dc7072acea",importPath:"../../../../packages/ui/src/components/Switch/demos/states",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Switch/demos/states/index.tsx"},"Switch.sync":{code:"import { useState } from 'react';\nimport { Block, Switch, Text } from '@platform-blocks/react-ui-library';\n\nconst PREFERENCE_CONTROLS = [\n  {\n    key: 'scoreAlerts',\n    label: 'Live score alerts',\n    description: 'Push notifications for scoring plays.'\n  },\n  {\n    key: 'newsEmails',\n    label: 'Breaking news emails',\n    description: 'Send a morning recap with roster updates.'\n  },\n  {\n    key: 'audioHighlights',\n    label: 'Audio highlights',\n    description: 'Play broadcast clips after each match.'\n  }\n] as const;\n\ntype PreferenceKey = (typeof PREFERENCE_CONTROLS)[number]['key'];\n\nconst INITIAL_SETTINGS: Record<PreferenceKey, boolean> = {\n  scoreAlerts: true,\n  newsEmails: false,\n  audioHighlights: false\n};\n\nexport function Demo() {\n  const [settings, setSettings] = useState<Record<PreferenceKey, boolean>>(\n    () => ({ ...INITIAL_SETTINGS })\n  );\n\n  return (\n    <Block>\n      <Block>\n        <Text variant=\"small\" color=\"muted\">\n          Shared state\n        </Text>\n        {PREFERENCE_CONTROLS.map(({ key, label, description }) => (\n          <Switch\n            key={key}\n            checked={settings[key]}\n            onChange={(checked) =>\n              setSettings((prev) => ({ ...prev, [key]: checked }))\n            }\n            label={label}\n            description={description}\n          />\n        ))}\n      </Block>\n  <Block>\n        <Text variant=\"small\" color=\"muted\">\n          Summary\n        </Text>\n        <Text variant=\"p\">\n          Score alerts are {settings.scoreAlerts ? 'on' : 'off'}.\n        </Text>\n        <Text variant=\"p\">\n          Breaking news emails are {settings.newsEmails ? 'on' : 'off'}.\n        </Text>\n        <Text variant=\"p\">\n          Audio highlights are {settings.audioHighlights ? 'on' : 'off'}.\n        </Text>\n      </Block>\n    </Block>\n  );\n}\n\n\n",hash:"04d4f009af7be8702ab4c8631198ab1e38671f1a17a4f6234ddbef83311482f2",importPath:"../../../../packages/ui/src/components/Switch/demos/sync",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Switch/demos/sync/index.tsx"},"Switch.thumb-label":{code:"import { useState } from 'react';\nimport { Block, Icon, Switch, Text, useTheme } from '@platform-blocks/react-ui-library';\n\nexport function Demo() {\n  const theme = useTheme();\n  const [wifi, setWifi] = useState<boolean>(true);\n  const [available, setAvailable] = useState<boolean>(true);\n\n  return (\n    <Block>\n      <Block>\n        <Text variant=\"small\" color=\"muted\">\n          Icon on the thumb \u2014 swaps with the on/off state\n        </Text>\n        <Switch\n          checked={wifi}\n          onChange={setWifi}\n          size=\"xl\"\n          label=\"Wi-Fi\"\n          onIcon={<Icon name=\"check\" size={18} color={theme.colors.primary[3]} stroke={3} />}\n          offIcon={<Icon name=\"close\" size={18} color={theme.colors.gray[5]} stroke={3} />}\n        />\n      </Block>\n\n      <Block>\n        <Text variant=\"small\" color=\"muted\">\n          Text label on the thumb\n        </Text>\n        <Switch\n          checked={available}\n          onChange={setAvailable}\n          size=\"3xl\"\n          color=\"success\"\n          label=\"Availability\"\n          onIcon={\n            <Text style={{ fontSize: 12, lineHeight: 11, fontWeight: '700', color: theme.colors.success[5] }}>\n              ON\n            </Text>\n          }\n          offIcon={\n            <Text style={{ fontSize: 12, lineHeight: 11, fontWeight: '700', color: theme.colors.gray[5] }}>\n              OFF\n            </Text>\n          }\n        />\n      </Block>\n    </Block>\n  );\n}\n",hash:"f81c6b86afbb07829a77d557c48fe461ff8fb8b629a50f2b295712780528ec0e",importPath:"../../../../packages/ui/src/components/Switch/demos/thumb-label",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Switch/demos/thumb-label/index.tsx"},"Switch.variants":{code:"import { useState } from 'react';\nimport { Block, Row, Switch, Text } from '@platform-blocks/react-ui-library';\n\nconst VARIANTS = [\n  { variant: 'filled', hint: 'filled (default) \u2014 solid track fills with the active color' },\n  { variant: 'outline', hint: 'outline \u2014 bordered track with a colored thumb' },\n  { variant: 'ios', hint: 'ios \u2014 large white thumb in a rounded pill track' },\n  { variant: 'android', hint: 'android \u2014 Material dot thumb that grows and whitens when on' },\n] as const;\n\nexport function Demo() {\n  const [on, setOn] = useState<Record<string, boolean>>({\n    filled: true,\n    outline: true,\n    ios: true,\n    android: true,\n  });\n\n  return (\n    <Block>\n      {VARIANTS.map(({ variant, hint }) => (\n        <Block key={variant}>\n          <Text variant=\"small\" color=\"muted\">\n            {hint}\n          </Text>\n          <Row gap=\"lg\" wrap=\"wrap\" align=\"center\">\n            <Switch\n              variant={variant}\n              checked={on[variant]}\n              onChange={(v) => setOn((prev) => ({ ...prev, [variant]: v }))}\n              label=\"On\"\n            />\n            <Switch variant={variant} checked={false} label=\"Off\" />\n            <Switch variant={variant} checked color=\"success\" label=\"Success\" />\n          </Row>\n        </Block>\n      ))}\n    </Block>\n  );\n}\n",hash:"e43e6e0dd35d02db1dd568e5294e262c894f2f877f45ca8da133595d23b78388",importPath:"../../../../packages/ui/src/components/Switch/demos/variants",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Switch/demos/variants/index.tsx"}}},3353,[]);
