__d(function(e,n,t,i,o,a,s){o.exports={"TableOfContents.active-callback":{code:"import { useRef, useState } from 'react';\nimport { Block, Chip, Row, TableOfContents, Text, Title, TitleRegistryProvider } from '@platform-blocks/react-ui-library';\n\nconst SECTIONS = [\n  { id: 'overview', title: 'Overview', summary: 'Explain when the progress indicator should appear.' },\n  { id: 'loading', title: 'Loading States', summary: 'Describe feedback while content is fetching.' },\n  { id: 'error', title: 'Error Recovery', summary: 'Clarify what happens if the data fails to load.' },\n];\n\nexport function Demo() {\n  const [activeId, setActiveId] = useState<string | null>(null);\n  const contentRef = useRef<HTMLDivElement | null>(null);\n\n  return (\n    <TitleRegistryProvider>\n      <Block>\n        <Chip variant=\"light\" color={activeId ? 'primary' : 'gray'} size=\"sm\">\n          Active section: {activeId ?? 'None'}\n        </Chip>\n\n        <Row gap=\"xl\" align=\"flex-start\">\n          <TableOfContents\n            container={contentRef.current ?? undefined}\n            variant=\"outline\"\n            size=\"xs\"\n            p=\"sm\"\n            style={{ width: 240 }}\n            onActiveChange={setActiveId}\n          />\n          <Block ref={contentRef} component=\"div\" grow={1} style={{ maxWidth: 560 }}>\n            {SECTIONS.map((section, index) => (\n              <Block key={section.id}>\n                <Title order={index === 0 ? 1 : 2}>{section.title}</Title>\n                <Text color=\"secondary\">{section.summary}</Text>\n              </Block>\n            ))}\n          </Block>\n        </Row>\n      </Block>\n    </TitleRegistryProvider>\n  );\n}\n",hash:"2ecd07d858f97b5164b33fc0845a97b9ca3884a19760bbc172175470ffe7b60a",importPath:"../../../../packages/ui/src/components/TableOfContents/demos/active-callback",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/TableOfContents/demos/active-callback/index.tsx"},"TableOfContents.basic":{code:"import { useRef } from 'react';\nimport { Block, Row, TableOfContents, Text, Title, TitleRegistryProvider } from '@platform-blocks/react-ui-library';\n\nconst SECTIONS = [\n  { id: 'intro', title: 'Introduction', summary: 'Set the stage for the walkthrough.' },\n  { id: 'setup', title: 'Setup', summary: 'Install dependencies and initialize the provider.' },\n  { id: 'usage', title: 'Usage', summary: 'Render headings inside your content area to register them.' },\n  { id: 'faq', title: 'FAQ', summary: 'Answer the questions you expect most often.' },\n];\n\nexport function Demo() {\n  const contentRef = useRef<HTMLDivElement | null>(null);\n\n  return (\n    <TitleRegistryProvider>\n      <Row gap=\"xl\" align=\"flex-start\">\n        <TableOfContents\n          container={contentRef.current ?? undefined}\n          variant=\"outline\"\n          size=\"sm\"\n          p=\"sm\"\n          style={{ width: 240 }}\n        />\n        <Block ref={contentRef} component=\"div\" grow={1} style={{ maxWidth: 560 }}>\n          {SECTIONS.map((section, index) => (\n            <Block key={section.id}>\n              <Title order={index === 0 ? 1 : 2}>{section.title}</Title>\n              <Text color=\"secondary\">{section.summary}</Text>\n            </Block>\n          ))}\n        </Block>\n      </Row>\n    </TitleRegistryProvider>\n  );\n}\n",hash:"88510dbbf7ee2f1a2db16355ea9d61e80ce3c529e5e67af5d9b5c3fbce040dfd",importPath:"../../../../packages/ui/src/components/TableOfContents/demos/basic",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/TableOfContents/demos/basic/index.tsx"},"TableOfContents.custom-initial":{code:"import { Block, TableOfContents } from '@platform-blocks/react-ui-library';\n\nconst INITIAL_ITEMS = [\n  { id: 'overview', value: 'Overview', depth: 1 },\n  { id: 'setup', value: 'Setup', depth: 2 },\n  { id: 'usage', value: 'Usage', depth: 2 },\n  { id: 'advanced', value: 'Advanced', depth: 1 },\n  { id: 'faq', value: 'FAQ', depth: 1 },\n];\n\nexport function Demo() {\n  return (\n    <Block align=\"flex-start\">\n      <TableOfContents\n        initialData={INITIAL_ITEMS}\n        variant=\"outline\"\n        depthOffset={16}\n        radius=\"sm\"\n        size=\"sm\"\n        p=\"sm\"\n        style={{ width: 240 }}\n      />\n    </Block>\n  );\n}\n",hash:"09b5d734998b6b5cf6b73a7d5d88a877e15a70534aafa20bbcf8fcfdb76d4770",importPath:"../../../../packages/ui/src/components/TableOfContents/demos/custom-initial",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/TableOfContents/demos/custom-initial/index.tsx"},"TableOfContents.depth-offset":{code:"import { Block, TableOfContents } from '@platform-blocks/react-ui-library';\n\nconst INITIAL_ITEMS = [\n  { id: 'intro', value: 'Introduction', depth: 1 },\n  { id: 'schedule', value: 'Release schedule', depth: 2 },\n  { id: 'api', value: 'API reference', depth: 2 },\n  { id: 'hooks', value: 'Hooks', depth: 3 },\n  { id: 'migration', value: 'Migration', depth: 1 },\n];\n\nexport function Demo() {\n  return (\n    <Block align=\"flex-start\">\n      <TableOfContents\n        initialData={INITIAL_ITEMS}\n        variant=\"outline\"\n        minDepthToOffset={2}\n        depthOffset={28}\n        size=\"xs\"\n        p=\"sm\"\n        style={{ width: 240 }}\n      />\n    </Block>\n  );\n}\n",hash:"c732e4499e11dd44f244715ca9de4c9596ee11196f359600b1a4804350b8fa99",importPath:"../../../../packages/ui/src/components/TableOfContents/demos/depth-offset",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/TableOfContents/demos/depth-offset/index.tsx"},"TableOfContents.variants":{code:"import { Row, TableOfContents } from '@platform-blocks/react-ui-library';\n\nconst ITEMS = [\n  { id: 'overview', value: 'Overview', depth: 1 },\n  { id: 'tokens', value: 'Color tokens', depth: 2 },\n  { id: 'accessibility', value: 'Accessibility', depth: 1 },\n];\n\nexport function Demo() {\n  return (\n    <Row gap=\"md\" align=\"flex-start\" wrap=\"wrap\">\n      <TableOfContents initialData={ITEMS} variant=\"outline\" size=\"xs\" style={{ width: 200 }} />\n      <TableOfContents initialData={ITEMS} variant=\"ghost\" size=\"xs\" style={{ width: 200 }} />\n      <TableOfContents\n        initialData={ITEMS}\n        variant=\"filled\"\n        color=\"primary.6\"\n        autoContrast\n        size=\"xs\"\n        style={{ width: 200 }}\n      />\n    </Row>\n  );\n}\n",hash:"b9d1c1dfb3bbbc853c250ff4ad96152c31d937aef1a2994e35c693e6c2d3f3d7",importPath:"../../../../packages/ui/src/components/TableOfContents/demos/variants",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/TableOfContents/demos/variants/index.tsx"}}},3355,[]);
__d(function(n,e,t,a,o,i,s){o.exports={"Tabs.animated":{code:"import { Block, Tabs, Text } from '@platform-blocks/react-ui-library';\n\nconst ITEMS = [\n  {\n    key: 'home',\n    label: 'Home',\n    content: (\n      <Block>\n        <Text weight=\"medium\">Welcome back</Text>\n        <Text color=\"muted\">\n          Animated transitions ease between dashboard sections and reinforce context shifts.\n        </Text>\n      </Block>\n    )\n  },\n  {\n    key: 'analytics',\n    label: 'Analytics',\n    content: (\n      <Block>\n        <Text weight=\"medium\">Analytics overview</Text>\n        <Text color=\"muted\">\n          Surface key charts and KPIs while the motion guides attention to new content.\n        </Text>\n      </Block>\n    )\n  },\n  {\n    key: 'settings',\n    label: 'Settings',\n    content: (\n      <Block>\n        <Text weight=\"medium\">Account settings</Text>\n        <Text color=\"muted\">\n          Manage notifications, billing, and other preferences without abrupt content swaps.\n        </Text>\n      </Block>\n    )\n  }\n];\n\nexport function Demo() {\n  return (\n    <Block>\n      <Tabs\n        variant=\"line\"\n        animated\n        animationDuration={250}\n        items={ITEMS}\n      />\n      <Text variant=\"small\" color=\"muted\">\n        Enable `animated` to add motion and use `animationDuration` to moderate the easing speed.\n      </Text>\n    </Block>\n  );\n}\n",hash:"3c60708487bc445985a59036ca153effed52bd259596678c8928fc4faebc4a4a",importPath:"../../../../packages/ui/src/components/Tabs/demos/animated",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Tabs/demos/animated/index.tsx"},"Tabs.basic":{code:"import { Block, Tabs, Text } from '@platform-blocks/react-ui-library';\n\nconst ITEMS = [\n  {\n    key: 'overview',\n    label: 'Overview',\n    content: <Text>High-level summary and entry point.</Text>\n  },\n  {\n    key: 'details',\n    label: 'Details',\n    content: <Text>Deeper dive into metrics and configuration.</Text>\n  },\n  {\n    key: 'activity',\n    label: 'Activity',\n    content: <Text>Recent events, tasks, and notifications.</Text>\n  }\n];\n\nexport function Demo() {\n  return (\n    <Block>\n      <Tabs items={ITEMS} />\n      <Text variant=\"small\" color=\"muted\">\n        Tabs render inline content directly below the active trigger by default.\n      </Text>\n    </Block>\n  );\n}\n",hash:"a8554a7504ef08cc7fc3a5838bd80cebc1cc11c5e68cd2de3f24b2f00f539f5b",importPath:"../../../../packages/ui/src/components/Tabs/demos/basic",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Tabs/demos/basic/index.tsx"},"Tabs.disabled":{code:"import { useState } from 'react';\nimport { Block, Tabs, Text, useTheme } from '@platform-blocks/react-ui-library';\n\nconst PANELS = [\n  {\n    key: 'overview',\n    label: 'Overview',\n    body: 'High-level snapshot of product activity and health.'\n  },\n  {\n    key: 'analytics',\n    label: 'Analytics',\n    body: 'Dive into usage metrics, adoption trends, and retention.'\n  },\n  {\n    key: 'billing',\n    label: 'Billing',\n    body: 'Billing is temporarily disabled while invoices reconcile.',\n    disabled: true\n  },\n  {\n    key: 'settings',\n    label: 'Settings',\n    body: 'Manage workspace preferences and security controls.'\n  }\n];\n\nexport function Demo() {\n  const theme = useTheme();\n  const [activeTab, setActiveTab] = useState('overview');\n  const [lastAttempt, setLastAttempt] = useState<string | null>(null);\n\n  return (\n    <Block>\n      <Tabs\n        activeTab={activeTab}\n        onTabChange={(tab) => {\n          setActiveTab(tab);\n          setLastAttempt(null);\n        }}\n        onDisabledTabPress={(key) => {\n          const label = PANELS.find((panel) => panel.key === key)?.label ?? key;\n          setLastAttempt(`${label} is currently disabled.`);\n        }}\n        variant=\"line\"\n        size=\"md\"\n        items={PANELS.map(({ body, ...panel }) => ({\n          ...panel,\n          content: (\n            <Block bg={theme.backgrounds.surface} borderColor={theme.backgrounds.border} radius=\"lg\" p=\"md\">\n              <Text>{body}</Text>\n            </Block>\n          )\n        }))}\n      />\n      <Text variant=\"small\" color=\"muted\">\n        Disable sensitive tabs while keeping the `onDisabledTabPress` callback to track attempted access.\n        {lastAttempt ? ` ${lastAttempt}` : ''}\n      </Text>\n    </Block>\n  );\n}\n",hash:"296cc1396ee347c821c7d7ad96bdb80a4cd28e933a38200982baa9db299c4dd5",importPath:"../../../../packages/ui/src/components/Tabs/demos/disabled",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Tabs/demos/disabled/index.tsx"},"Tabs.interactive":{code:"import { useState } from 'react';\nimport { Block, Tabs, Text } from '@platform-blocks/react-ui-library';\n\nconst ITEMS = [\n  {\n    key: 'dashboard',\n    label: '\ud83c\udfe0 Dashboard',\n    content: <Text>Monitor analytics across teams and products.</Text>\n  },\n  {\n    key: 'settings',\n    label: '\u2699\ufe0f Settings',\n    content: <Text>Configure notifications, permissions, and integrations.</Text>\n  },\n  {\n    key: 'profile',\n    label: '\ud83d\udc64 Profile',\n    content: <Text>Review contact details, roles, and security options.</Text>\n  }\n];\n\nexport function Demo() {\n  const [activeTab, setActiveTab] = useState('dashboard');\n  const activeLabel = ITEMS.find((item) => item.key === activeTab)?.label ?? activeTab;\n\n  return (\n    <Block>\n      <Tabs activeTab={activeTab} onTabChange={setActiveTab} items={ITEMS} />\n      <Text variant=\"small\" color=\"muted\">\n        Active tab: {activeLabel}\n      </Text>\n    </Block>\n  );\n}\n",hash:"93e6073c2ce1135f84c7d24a291c79274f0cc2c6969ece1f76e113772fc71267",importPath:"../../../../packages/ui/src/components/Tabs/demos/interactive",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Tabs/demos/interactive/index.tsx"},"Tabs.location":{code:"import { Block, Tabs, Text } from '@platform-blocks/react-ui-library';\n\ntype Location = 'start' | 'end';\n\nconst SECTIONS: Array<{ label: string; location: Location; helper: string }> = [\n  {\n    label: 'Tabs above content (start)',\n    location: 'start',\n    helper: 'Default placement keeps triggers directly above the active view.'\n  },\n  {\n    label: 'Tabs below content (end)',\n    location: 'end',\n    helper: 'Use end placement when the content should lead and controls follow.'\n  }\n];\n\nconst buildItems = (location: Location) => [\n  {\n    key: 'home',\n    label: 'Home',\n    content: (\n      <Text>\n        Home content rendered with tabs {location === 'start' ? 'above' : 'below'} the panel.\n      </Text>\n    )\n  },\n  {\n    key: 'settings',\n    label: 'Settings',\n    content: (\n      <Text>\n        Update configurations while keeping the tabs {location === 'start' ? 'up top' : 'after the details'}.\n      </Text>\n    )\n  },\n  {\n    key: 'profile',\n    label: 'Profile',\n    content: (\n      <Text>\n        Profile information with navigation {location === 'start' ? 'leading into' : 'following'} the content.\n      </Text>\n    )\n  }\n];\n\nexport function Demo() {\n  return (\n    <Block>\n      {SECTIONS.map(({ label, location, helper }) => (\n        <Block key={location}>\n          <Text weight=\"medium\">{label}</Text>\n          <Tabs variant=\"line\" location={location} items={buildItems(location)} />\n          <Text variant=\"small\" color=\"muted\">\n            {helper}\n          </Text>\n        </Block>\n      ))}\n    </Block>\n  );\n}\n",hash:"3cdff34798714262e282e90302ae512b251c2c612e4e4e5c51a0e1bba5b8a526",importPath:"../../../../packages/ui/src/components/Tabs/demos/location",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Tabs/demos/location/index.tsx"},"Tabs.navigation-only":{code:"import { useMemo, useState } from 'react';\nimport { Block, Tabs, Text, useTheme } from '@platform-blocks/react-ui-library';\n\nconst NAV_ITEMS = [\n  { key: 'home', label: 'Home' },\n  { key: 'products', label: 'Products' },\n  { key: 'about', label: 'About' },\n  { key: 'contact', label: 'Contact' }\n] as const;\n\nconst CONTENT_COPY: Record<typeof NAV_ITEMS[number]['key'], string> = {\n  home: 'Welcome back! Navigation only mode keeps the tab strip separated from the view.',\n  products: 'Highlight product cards, filters, or category grids below the navigation.',\n  about: 'Share the company story, values, and milestones alongside persistent tabs.',\n  contact: 'Surface support channels and locations while the navigation stays fixed.'\n};\n\nexport function Demo() {\n  const theme = useTheme();\n  const [activeTab, setActiveTab] = useState<typeof NAV_ITEMS[number]['key']>('home');\n\n  const items = useMemo(\n    () => NAV_ITEMS.map(({ key, label }) => ({ key, label, content: null })),\n    []\n  );\n\n  return (\n    <Block>\n      <Tabs\n        items={items}\n        activeTab={activeTab}\n        onTabChange={(tabKey) => setActiveTab(tabKey as typeof NAV_ITEMS[number]['key'])}\n        variant=\"chip\"\n        navigationOnly\n      />\n      <Block bg={theme.backgrounds.surface} borderColor={theme.backgrounds.border} radius=\"lg\" p=\"lg\">\n        <Text>{CONTENT_COPY[activeTab]}</Text>\n      </Block>\n      <Text variant=\"small\" color=\"muted\">\n        `navigationOnly` renders just the triggers so you can manage layout and transitions for the content area yourself.\n      </Text>\n    </Block>\n  );\n}\n",hash:"b9577da840d9bb4f006e99fe6c215c0559fa9e9d085e2d1d2c47b1bde1940129",importPath:"../../../../packages/ui/src/components/Tabs/demos/navigation-only",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Tabs/demos/navigation-only/index.tsx"},"Tabs.orientation":{code:"import { Block, Tabs, Text } from '@platform-blocks/react-ui-library';\n\ntype Orientation = 'horizontal' | 'vertical';\n\nconst buildItems = (orientation: Orientation) => [\n  {\n    key: 'general',\n    label: 'General',\n    content: (\n      <Text>\n        Broad overview content rendered with a {orientation} tab list.\n      </Text>\n    )\n  },\n  {\n    key: 'security',\n    label: 'Security',\n    content: (\n      <Text>\n        Security controls and permissions laid out for a {orientation} arrangement.\n      </Text>\n    )\n  },\n  {\n    key: 'notifications',\n    label: 'Notifications',\n    content: (\n      <Text>\n        Configure alerts and digests with triggers stacked {orientation === 'vertical' ? 'in a column' : 'in a row'}.\n      </Text>\n    )\n  }\n];\n\nconst ORIENTATIONS: Array<{ label: string; orientation: Orientation; helper: string }> = [\n  {\n    label: 'Horizontal orientation',\n    orientation: 'horizontal',\n    helper: 'Default layout presents tabs in a row for top-level navigation.'\n  },\n  {\n    label: 'Vertical orientation',\n    orientation: 'vertical',\n    helper: 'Vertical tab lists are ideal for settings sidebars and dense menus.'\n  }\n];\n\nexport function Demo() {\n  return (\n    <Block>\n      {ORIENTATIONS.map(({ label, orientation, helper }) => (\n        <Block key={orientation}>\n          <Text weight=\"medium\">{label}</Text>\n          <Tabs orientation={orientation} items={buildItems(orientation)} />\n          <Text variant=\"small\" color=\"muted\">\n            {helper}\n          </Text>\n        </Block>\n      ))}\n    </Block>\n  );\n}\n",hash:"555b673b79d8d74e5cb7914b24aa4d912699b23d01921b22622877fdaba1b33a",importPath:"../../../../packages/ui/src/components/Tabs/demos/orientation",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Tabs/demos/orientation/index.tsx"},"Tabs.variants":{code:"import type { ComponentProps } from 'react';\nimport { Block, Tabs, Text } from '@platform-blocks/react-ui-library';\n\ntype Variant = NonNullable<ComponentProps<typeof Tabs>['variant']>;\n\nconst VARIANT_DEMOS: Array<{\n  heading: string;\n  variant: Variant;\n  helper: string;\n  items: Array<{ key: string; label: string; description: string }>;\n}> = [\n  {\n    heading: 'Line variant',\n    variant: 'line',\n    helper: 'Minimal underline style aligns with primary navigation patterns.',\n    items: [\n      { key: 'documents', label: 'Documents', description: 'Underline emphasizes the active document view.' },\n      { key: 'images', label: 'Images', description: 'Great for media browsers with subtle hierarchy.' },\n      { key: 'videos', label: 'Videos', description: 'Pairs well with narrow tab bars and dense content.' }\n    ]\n  },\n  {\n    heading: 'Chip variant',\n    variant: 'chip',\n    helper: 'Rounded pills feel tactile and work well for filters or secondary navigation.',\n    items: [\n      { key: 'overview', label: 'Overview', description: 'Pills highlight the selected state with a filled background.' },\n      { key: 'details', label: 'Details', description: 'Suitable for segmented controls or inline filters.' },\n      { key: 'settings', label: 'Settings', description: 'Works nicely for preference toggles.' }\n    ]\n  },\n  {\n    heading: 'Folder variant',\n    variant: 'folder',\n    helper: 'Raised folder styling evokes classic tabbed interfaces.',\n    items: [\n      { key: 'overview-folder', label: 'Overview', description: 'Ideal for dashboards with nested content.' },\n      { key: 'details-folder', label: 'Details', description: 'Tabs feel like document dividers for data-heavy views.' },\n      { key: 'settings-folder', label: 'Settings', description: 'Keeps controls organized in admin interfaces.' }\n    ]\n  }\n];\n\nexport function Demo() {\n  return (\n    <Block>\n      {VARIANT_DEMOS.map(({ heading, variant, helper, items }) => (\n        <Block key={variant}>\n          <Text weight=\"medium\">{heading}</Text>\n          <Tabs\n            variant={variant}\n            items={items.map(({ description, ...item }) => ({\n              ...item,\n              content: <Text>{description}</Text>\n            }))}\n          />\n          <Text variant=\"small\" color=\"muted\">\n            {helper}\n          </Text>\n        </Block>\n      ))}\n    </Block>\n  );\n}\n",hash:"1596bfc2e821328b856f5befd9107ecaadc6ec503721697d12505505b19fa1a1",importPath:"../../../../packages/ui/src/components/Tabs/demos/variants",githubUrl:"https://github.com/platform-blocks/react-ui-library/blob/main/packages/ui/src/components/Tabs/demos/variants/index.tsx"}}},3356,[]);
